exports.body:
function lookupSourceId(e: ExecutedExploration): string {
	return `${e.exploration.type} [${e.exploration.id}]`;
}

function reportFromLookups(results: readonly ExecutedExploration[]): AnswerReport {
	const sources: ReportSource[] = results.map((r): ReportSource => {
		const base = { sourceId: lookupSourceId(r), sourceKind: 'lookup' as const };
		const out = r.output;
		if (out.type === 'failed')      return { ...base, failure: out.message };
		if (out.type === 'unsupported') return { ...base, failure: `the lookup is not supported: ${out.reason}` };
		const completeness = (out as { completeness?: unknown }).completeness;
		return isCompletenessRecord(completeness) ? { ...base, completeness } : { ...base, failure: NO_COMPLETENESS_RECORD };
	});
	return deriveAnswerReport(sources);
}

exports.signature:
runCapabilityReuseCheck(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The model that judges the candidates; a test passes a stand-in. */
	narrowProvider?: LLMProvider,
): Promise<CapabilityReuseCheckOutput>

exports.body:
async function runCapabilityReuseCheck(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The model that judges the candidates; a test passes a stand-in. */
	narrowProvider?: LLMProvider,
): Promise<CapabilityReuseCheckOutput> {
	const prepared = await prepareCapabilityReuseCheck(exp, ctx);
	if (prepared.kind === 'short-circuit') return prepared.shortCircuit;

	// LLM narrow pass -- daemon-side shaperProvider. When the model cannot be
	// called the lookup could not run: no candidate was judged, and showing
	// every one as `unrelated` would read as a judgement. It throws, with the
	// candidates it had found, and the executor reports the lookup as failed.
	let raw: CapabilityReuseCheckLLMOutput;
	try {
		const cfg = loadAnalyzeConfig();
		const provider = narrowProvider ?? resolveRoleProvider('analyze.narrow', cfg);
		raw = await provider.completeStructured<CapabilityReuseCheckLLMOutput>(
			[
				{ role: 'system', content: prepared.systemPrompt },
				{ role: 'user',   content: prepared.userTurn     },
			],
			CAPABILITY_VERDICTS_SCHEMA,
			{
				maxAttempts:     cfg.shaper.structuredOutputRetries,
				disableThinking: true,
				maxTokens:       2_048,
			},
		);
		log.info(
			{
				runId:      ctx.runId,
				capability: prepared.prepared.capability,
				returned:   raw.verdicts.length,
			},
			'capability.reuse-check: LLM verdicts received',
		);
	} catch (err) {
		throw new LookupFailedError(
			`capability.reuse-check: the model call that judges the candidates failed: ${errorMessage(err)}`,
			prepared.prepared.profiles.map(p => ({
				source:  p.path,
				content: p.profile !== undefined
					? `candidate module, not judged; exports: ${p.profile.exports.slice(0, 8).join(', ') || '(none)'}`
					: 'candidate module, not judged; its profile could not be read',
			})),
			{ cause: err },
		);
	}

	return finalizeCapabilityReuseCheck(prepared.prepared, raw, undefined, ctx.runId);
}

async function prepareCapabilityReuseCheck(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<CapabilityReuseCheckPrepareResult> {
	const params = parseParams(exp);
	const capability = params.capability;
	const limit = params.limit ?? DEFAULT_LIMIT;

	// (1) concept.resolve for module candidates.
	const conceptExp: Exploration = {
		id:      `${exp.id}-inner-concept`,
		type:    'concept.resolve',
		purpose: `capability.reuse-check inner concept.resolve for "${capability}"`,
		params: {
			query:        capability,
			limit:        Math.max(limit * 2, 10),
			includeKinds: ['dir', 'file'],
		},
	};
	const concept = await runConceptResolve(conceptExp, ctx);

	if (concept.hits.length === 0) {
		log.info(
			{ runId: ctx.runId, capability },
			'capability.reuse-check: concept.resolve returned no hits',
		);
		return {
			kind: 'short-circuit',
			shortCircuit: {
				type:         'capability.reuse-check',
				// The inner module search found nothing to check; its own record says whether it could look.
				completeness: concept.completeness,
				capability,
				candidates:   [],
				notFoundNote: `No modules matched "${capability}" via concept.resolve.`,
			},
		};
	}

	const topHits = pickTopDistinct(concept.hits, limit);

	// (2) module.profile each candidate serially.
	const profiles: Array<{ path: string; profile: ModuleProfile | undefined; score: number }> = [];
	const skipped: SkippedItem[] = [];
	for (const h of topHits) {
		const profileExp: Exploration = {
			id:      `${exp.id}-inner-profile-${h.path}`,
			type:    'module.profile',
			purpose: `capability.reuse-check inner module.profile for ${h.path}`,
			params:  { path: h.path },
		};
		try {
			const prof = await runModuleProfile(profileExp, ctx);
			profiles.push({ path: h.path, profile: prof.profile, score: h.score });
		} catch (err) {
			log.warn(
				{ runId: ctx.runId, path: h.path, err: (err as Error).message },
				'capability.reuse-check: module.profile failed for candidate; keeping as unrelated placeholder',
			);
			profiles.push({ path: h.path, profile: undefined, score: h.score });
			skipped.push({
				what:   h.path,
				reason: `its profile could not be read (${(err as Error).message}), so the model judged it without one`,
			});
		}
	}

	// Candidates: the inner search may have cut its matches, and only `limit` of them are checked.
	// The inner search's own limits bound what the candidates were drawn from.
	const limited: ReachedLimit[] = (concept.completeness.limited ?? []).map(l => ({ ...l, scope: 'source' as const }));
	const distinctHits = new Set(concept.hits.map(h => h.path)).size;
	if (distinctHits > topHits.length) {
		limited.push(reachedLimit('candidate modules', limit, 'overall', distinctHits));
	}

	const promptContent = loadPromptFile();
	const messages = buildMessages(promptContent, capability, profiles);
	const systemMsg = messages[0]!.content as string;
	const userMsg   = messages[1]!.content as string;

	return {
		kind:         'narrow-llm',
		systemPrompt: systemMsg,
		userTurn:     userMsg,
		schema:       CAPABILITY_VERDICTS_SCHEMA,
		prepared: {
			capability,
			profiles,
			conceptHits: concept.hits.length,
			completenessFacts: { limited, skipped },
		},
	};
}

function finalizeCapabilityReuseCheck(
	prepared:      CapabilityReuseCheckPrepared,
	raw:           CapabilityReuseCheckLLMOutput | undefined,
	llmSkipReason: string | undefined,
	runId?:        string,
): CapabilityReuseCheckOutput {
	const verdicts = new Map<string, { verdict: CapabilityReuseCandidate['verdict']; rationale: string }>();
	if (raw !== undefined) {
		for (const v of raw.verdicts) {
			if (typeof v.path !== 'string' || v.path.length === 0) continue;
			verdicts.set(v.path, { verdict: v.verdict, rationale: v.rationale });
		}
	}

	const candidates: CapabilityReuseCandidate[] = prepared.profiles.map(p => {
		const v = verdicts.get(p.path);
		const evidenceEntities = p.profile !== undefined
			? p.profile.exports.slice(0, 5)
			: [];
		return {
			path:             p.path,
			moduleName:       basenameOf(p.path),
			verdict:          v?.verdict ?? 'unrelated',
			rationale:        v?.rationale ?? (llmSkipReason !== undefined
				? 'LLM verdict unavailable; ranked purely by concept.resolve score.'
				: 'LLM emitted no verdict for this path.'),
			evidenceEntities,
			conceptScore:     Math.round(p.score * 1_000) / 1_000,
		};
	});

	log.info(
		{
			runId,
			capability: prepared.capability,
			hits:       prepared.conceptHits,
			candidates: candidates.length,
			skippedLLM: llmSkipReason !== undefined,
		},
		'capability.reuse-check: complete',
	);

	// A candidate the model gave no verdict for is shown as 'unrelated' by default.
	const unjudged: SkippedItem[] = llmSkipReason !== undefined ? [] : prepared.profiles
		.filter(p => !verdicts.has(p.path))
		.map(p => ({ what: p.path, reason: "the model gave no verdict for it; it is shown as 'unrelated' by default" }));
	const facts = prepared.completenessFacts;
	const completeness = llmSkipReason !== undefined
		? buildCompleteness({
			returned: candidates.length, basis: 'graph', notEstablished: true,
			basisNote: `${GRAPH_BASIS_NOTE}. No candidate was judged (${llmSkipReason}); every candidate is shown as 'unrelated' by default`,
		})
		: carriedCompleteness(
			candidates.length,
			'graph',
			facts === undefined ? undefined : { ...facts, skipped: [...(facts.skipped ?? []), ...unjudged] },
			GRAPH_BASIS_NOTE,
		);

	return {
		type:         'capability.reuse-check',
		completeness,
		capability:   prepared.capability,
		candidates,
		notFoundNote: '',
		...(llmSkipReason !== undefined ? { llmSkipReason } : {}),
	};
}

async function runClassHierarchy(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<ClassHierarchyOutput> {
	const params = parseParams(exp);
	const db = await getDb();
	const subject = params.symbolName ?? params.entityId ?? '';

	// (1) Resolve target(s). entityId path -> single node; symbolName
	// path -> every matching class/interface in the repo (a name like
	// `Extractor` may repeat across sub-packages, so we surface all).
	let targets: Entity[];
	if (params.entityId !== undefined) {
		const row = await getEntity(db, params.entityId);
		targets = row !== null ? [row] : [];
	} else {
		targets = await findEntitiesByName(
			db,
			[params.symbolName!],
			{ repo: ctx.repoPath, kinds: TARGET_KINDS },
		);
		// Prefer real definitions over test/spec doubles.
		targets = targets.filter(e => e.artifact !== true);
	}
	// Drop targets that live under a currently-gitignored path.
	// `class Extractor` compiled into out/insrc/ shouldn't resolve
	// alongside the source `class Extractor` in src/insrc/.
	targets = targets.filter(e => ctx.ignoreFilter.isIncluded(e.file));

	if (targets.length === 0) {
		log.info(
			{ runId: ctx.runId, subject },
			'class.hierarchy: no target resolved',
		);
		return {
			type:         'class.hierarchy',
			// The graph holds no class or interface of this name: empty, and complete.
			completeness: graphCompleteness({ returned: 0 }),
			subject,
			nodes:        [],
			notFoundNote: `No class/interface named "${subject}" found in the repo.`,
		};
	}

	// (2) Traverse INHERITS + IMPLEMENTS in both directions per target.
	const nodes: ClassHierarchyNode[] = [];
	const noGraphNode: Entity[] = [];
	for (const t of targets) {
		const u64 = await entityU64ForId(t.id);
		if (u64 === undefined) { noGraphNode.push(t); continue; }

		const inheritsOut   = await outNeighbors(u64, { kindFilter: ['INHERITS'] });
		const implementsOut = await outNeighbors(u64, { kindFilter: ['IMPLEMENTS'] });
		const inheritsIn    = await inNeighbors(u64,  { kindFilter: ['INHERITS'] });
		const implementsIn  = await inNeighbors(u64,  { kindFilter: ['IMPLEMENTS'] });

		const extendsIds     = await entityIdsByU64s(inheritsOut);
		const implementsIds  = await entityIdsByU64s(implementsOut);
		const subclassIds    = await entityIdsByU64s(inheritsIn);
		const implementerIds = await entityIdsByU64s(implementsIn);

		// Drop neighbors under gitignored paths so a compiled-JS class
		// under out/ doesn't show up alongside the authored source
		// class as a phantom subclass or implementer.
		const includeE = (e: Entity): boolean => ctx.ignoreFilter.isIncluded(e.file);
		const extendsEnts     = (await hydrate(extendsIds)).filter(includeE);
		const implementsEnts  = (await hydrate(implementsIds)).filter(includeE);
		const subclassEnts    = (await hydrate(subclassIds)).filter(includeE);
		const implementerEnts = (await hydrate(implementerIds)).filter(includeE);

		nodes.push({
			entityId:  t.id,
			name:      t.name,
			kind:      t.kind,
			file:      t.file,
			startLine: t.startLine,
			extendsList:    extendsEnts.map(e => ({
				entityId: e.id,
				name:     e.name,
				file:     e.file,
			})),
			implementsList: implementsEnts.map(e => ({
				entityId: e.id,
				name:     e.name,
				file:     e.file,
			})),
			subclasses:     subclassEnts.map(e => ({
				entityId: e.id,
				name:     e.name,
				file:     e.file,
			})),
			implementers:   implementerEnts.map(e => ({
				entityId: e.id,
				name:     e.name,
				file:     e.file,
			})),
		});
	}

	log.info(
		{
			runId:   ctx.runId,
			subject,
			targets: targets.length,
			nodes:   nodes.length,
		},
		'class.hierarchy: complete',
	);

	return {
		type:         'class.hierarchy',
		completeness: graphCompleteness({
			returned: nodes.length,
			found:    targets.length,
			skipped:  noGraphNode.map(e => ({
				what:   `${e.name} (${e.file}:${e.startLine})`,
				reason: 'the class has no node in the stored graph, so its hierarchy was not read',
			})),
		}),
		subject,
		nodes,
		notFoundNote: '',
	};

	async function hydrate(idMap: Map<bigint, string>): Promise<Entity[]> {
		const stringIds: string[] = [];
		for (const sid of idMap.values()) stringIds.push(sid);
		if (stringIds.length === 0) return [];
		return getEntitiesByIds(db, stringIds);
	}
}

function vectorPassSkipped(reason: string | undefined): SkippedItem[] {
	return reason === undefined ? [] : [{
		what:   "the document index's search by meaning",
		reason: `${reason}; only sections that contain the query's words are included`,
	}];
}

function reachedLimit(
	what:  string,
	limit: number,
	scope: ReachedLimit['scope'],
	found: number | null,
): ReachedLimit {
	return {
		what, limit, scope,
		reason: found !== null
			? `${found} ${what} were found and ${limit} are kept`
			: `the lookup stops at ${limit} ${what}; how many exist is not known`,
	};
}

exports.signature:
graphCompleteness(args: {
	readonly returned:  number;
	readonly found?:    number | null | undefined;
	readonly limited?:  readonly ReachedLimit[] | undefined;
	readonly skipped?:  readonly SkippedItem[] | undefined;
	readonly partlyRead?: readonly PartlyReadItem[] | undefined;
	/** A rule of this lookup that bounds what it looks at, added to the basis note. */
	readonly rule?:     string | undefined;
}): Completeness

exports.body:
function graphCompleteness(args: {
	readonly returned:  number;
	readonly found?:    number | null | undefined;
	readonly limited?:  readonly ReachedLimit[] | undefined;
	readonly skipped?:  readonly SkippedItem[] | undefined;
	readonly partlyRead?: readonly PartlyReadItem[] | undefined;
	/** A rule of this lookup that bounds what it looks at, added to the basis note. */
	readonly rule?:     string | undefined;
}): Completeness {
	return buildCompleteness({
		returned:  args.returned,
		...(args.found   !== undefined ? { total: args.found }     : {}),
		...(args.limited !== undefined ? { limited: args.limited } : {}),
		...(args.skipped !== undefined ? { skipped: args.skipped } : {}),
		...(args.partlyRead !== undefined ? { partlyRead: args.partlyRead } : {}),
		basis:     'graph',
		basisNote: args.rule !== undefined ? `${GRAPH_BASIS_NOTE}. ${args.rule}` : GRAPH_BASIS_NOTE,
	});
}

function textSearchCompleteness(data: SearchGrepData, limit: number): Completeness {
	const o = data.omitted;
	const limited: ReachedLimit[] = [];
	if (data.truncated) {
		limited.push({
			what: 'hits', limit, scope: 'overall',
			reason: `the search stops at ${limit} hits; how many more lines match is not known`,
		});
	}
	if (o.perFileLimitReached) {
		limited.push({
			what: 'hits per file', limit, scope: 'per-group',
			reason: `ripgrep stops at ${limit} matches in each file; a file that reached it may hold more`,
		});
	}
	const skipped: SkippedItem[] = o.skippedFiles.map(f => ({
		what:   f.path,
		reason: f.reason === 'too-large' ? 'the file is over the 2 MB size limit' : 'it could not be read',
	}));
	if (o.outputDiscarded) {
		skipped.push({ what: "part of the search's output", reason: "it passed the 4 MB the search keeps and was dropped" });
	}
	const partlyRead: PartlyReadItem[] = o.shortenedLines.map(l => ({
		what:       `${l.path}:${l.line}`,
		readChars:  Math.min(500, l.totalChars),
		totalChars: l.totalChars,
	}));
	const notes = [`Not searched, by rule: ${o.excludedByRule}.`];
	if (o.backendFallback !== undefined) {
		notes.push(`ripgrep did not finish (${o.backendFallback.detail}); the result is the Node search's.`);
	}
	return buildCompleteness({
		returned: data.hits.length,
		limited, skipped, partlyRead,
		basis:     'text',
		basisNote: notes.join(' '),
	});
}

function carriedCompleteness(
	returned: number,
	basis:    Completeness['basis'],
	facts:    CarriedCompletenessFacts | undefined,
	note?:    string,
): Completeness {
	if (facts === undefined) {
		const missing = 'what the lookup left out was not carried from its first step, so its completeness is not established';
		return buildCompleteness({
			returned, basis, notEstablished: true,
			basisNote: note !== undefined ? `${note}. ${missing}` : missing,
		});
	}
	return buildCompleteness({
		returned, basis,
		...(facts.limited    !== undefined ? { limited: facts.limited }       : {}),
		...(facts.skipped    !== undefined ? { skipped: facts.skipped }       : {}),
		...(facts.partlyRead !== undefined ? { partlyRead: facts.partlyRead } : {}),
		...(note !== undefined ? { basisNote: note } : {}),
	});
}

async function runConceptResolve(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<ConceptResolveOutput> {
	const params = parseParams(exp);
	const tokens = tokenise(params.query);
	if (tokens.length === 0) {
		log.debug({ query: params.query }, 'concept.resolve: no salient tokens');
		return { type: 'concept.resolve', completeness: noQueryCompleteness(), query: params.query, hits: [] };
	}

	const structuralBoost = tokens.some(t => STRUCTURAL_TOKENS.has(t));

	// STRUCTURAL_TOKENS signal INTENT (this is a structural query,
	// give dirs a bonus). They should NOT count as candidate matches
	// themselves -- otherwise a file named `messaging_module_guide.md`
	// gets a bogus "module" name-token hit that lets it beat the
	// actual `insors/core/messaging/` directory. Filter them out of
	// the matching set.
	const matchTokens = tokens.filter(t => !STRUCTURAL_TOKENS.has(t));
	if (matchTokens.length === 0) {
		log.debug({ query: params.query, tokens }, 'concept.resolve: no non-structural tokens; empty result');
		return { type: 'concept.resolve', completeness: noQueryCompleteness(), query: params.query, hits: [] };
	}

	const includeKinds = params.includeKinds ?? ['dir', 'file', 'entity'];

	const db = await getDb();
	const entities = await listEntitiesForRepo(db, ctx.repoPath);

	// Assemble the candidate pool.
	const rawCandidates: Candidate[] = [];
	const skipped: SkippedItem[] = [];
	if (includeKinds.includes('dir'))    rawCandidates.push(...enumerateDirs(ctx.repoPath, ctx.ignoreFilter, skipped));
	if (includeKinds.includes('file'))   rawCandidates.push(...fileCandidatesFromEntities(entities, ctx.ignoreFilter));
	if (includeKinds.includes('entity')) rawCandidates.push(...structuralEntityCandidates(entities, ctx.ignoreFilter));

	// Annotate every candidate with an entityCount so the density
	// signal can discriminate real code modules from empty docs
	// dirs that share a name.
	const candidates = annotateEntityCounts(rawCandidates, entities);

	// Score every candidate. Drop zero-hit candidates inline.
	const scored: ScoredCandidate[] = [];
	for (const c of candidates) {
		const s = scoreCandidate(c, matchTokens, ctx.repoPath, structuralBoost);
		if (s !== null) scored.push(s);
	}

	// Dedup by (kind, path) preferring the higher score. Rare edge
	// case where the same path is enumerated via multiple candidate
	// paths.
	const byKey = new Map<string, ScoredCandidate>();
	for (const s of scored) {
		const k = `${s.kind}:${s.path}`;
		const prev = byKey.get(k);
		if (prev === undefined || s.score > prev.score) byKey.set(k, s);
	}

	// A limit below 1 is not a limit a result can be cut to: at least one hit is kept.
	const limit = Math.max(1, Math.floor(params.limit ?? MAX_HITS));
	const ranked = Array.from(byKey.values())
		.sort((a, b) => b.score - a.score)
		.slice(0, limit);

	const hits: ConceptHit[] = ranked.map(r => ({
		kind:  r.kind,
		path:  r.path,
		name:  r.name,
		...(r.entityId !== undefined ? { entityId: r.entityId } : {}),
		score: Math.round(r.score * 1000) / 1000,
		diagnostics: {
			...(r.diagnostics.tokenMatch !== undefined ? { tokenMatch: Math.round(r.diagnostics.tokenMatch * 1000) / 1000 } : {}),
			...(r.diagnostics.pathDepth !== undefined ? { pathDepth:  r.diagnostics.pathDepth } : {}),
			...(r.diagnostics.entityDensity !== undefined ? { graphInDegree: Math.round(r.diagnostics.entityDensity * 1000) / 1000 } : {}),
		},
	}));

	log.info(
		{
			runId:   ctx.runId,
			query:   params.query,
			tokens,
			candidateCount: candidates.length,
			scoredCount:    scored.length,
			returnedCount:  hits.length,
			topPath: hits[0]?.path,
		},
		'concept.resolve: complete',
	);

	return {
		type: 'concept.resolve',
		completeness: graphCompleteness({
			returned: hits.length,
			found:    byKey.size,
			limited:  byKey.size > limit ? [reachedLimit('matches', limit, 'overall', byKey.size)] : [],
			skipped,
			rule:     `Directories more than ${MAX_DIR_DEPTH} levels below the repository root are not candidates.`,
		}),
		query: params.query,
		hits,
	};
}

async function runConfigTrace(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<ConfigTraceOutput> {
	const params = parseParams(exp);
	const root = params.path !== undefined
		? scopedPath(params.path, ctx.repoPath)
		: ctx.repoPath;

	// Build a pattern that catches the literal + common quoting.
	// Escape regex-special chars so `foo.bar[0]`-style keys survive.
	const literal = escapeRegex(params.key);

	// At least 1, as the search itself enforces: a topK below 1 floors to 0.
	const limit = Math.max(1, params.topK ?? DEFAULT_TOP_K);
	// A search that could not run throws, and the executor reports the lookup as
	// failed. It does not return an empty result: that would read as "nothing matches".
	const data = await runGrepSearch({
		pattern: literal,
		root,
		caseInsensitive: false,
		limit,
	});

	const hits: ConfigTraceHit[] = data.hits.map(h => {
		const abs = h.path.startsWith('/') ? h.path : `${root}/${h.path}`;
		return {
			file: abs,
			line: h.line,
			text: h.text,
			role: classifyRole(abs, h.text, params.key),
		};
	});

	log.info(
		{
			runId:     ctx.runId,
			key:       params.key,
			backend:   data.usedRipgrep ? 'ripgrep' : 'node',
			hits:      hits.length,
			truncated: data.truncated,
		},
		'config.trace: complete',
	);

	return {
		type:      'config.trace',
		completeness: textSearchCompleteness(data, limit),
		key:       params.key,
		hits,
		backend:   data.usedRipgrep ? 'ripgrep' : 'node',
		root:      data.root,
	};
}

function classifyRole(file: string, text: string, key: string): ConfigTraceRole {
	const ext = extname(file).toLowerCase();
	const isConfig = CONFIG_EXTS.has(ext);
	const t = text.trim();

	// Bare mention in a code-file comment reads as documentation, not
	// a live use. Comment-line detection is language-lite: `#`, `//`,
	// `/*`, `--`, `>` (markdown quote).
	if (!isConfig && (t.startsWith('#') || t.startsWith('//') || t.startsWith('/*') || t.startsWith('--'))) {
		return 'unknown';
	}

	// Default-value read: `getenv(KEY, X)`, `get(KEY, X)`, `??`, `||`
	// after the key.
	const defaultRx = new RegExp(
		`(?:getenv|get|getOr|env|settings|config)\\s*[\\(\\[]\\s*['"\`]?${escapeRegex(key)}['"\`]?\\s*[,)]`,
		'i',
	);
	if (defaultRx.test(t) && /,\s*[^)]+/.test(t.slice(t.indexOf(key) + key.length))) {
		return 'default';
	}

	// Config-file line: assignment or key-value shape.
	if (isConfig) return 'definition';

	// Source-file assignment: `KEY = ...`, `"key": ...`, `KEY ?= ...`.
	const assignRx = new RegExp(
		`^\\s*(export\\s+)?(const|let|var|final|public|private)?\\s*['"\`]?${escapeRegex(key)}['"\`]?\\s*[:=]`,
		'i',
	);
	if (assignRx.test(t)) return 'definition';

	// Read access -- treat as usage.
	if (t.includes(key)) return 'usage';
	return 'unknown';
}

async function runConventionDetect(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<ConventionDetectOutput> {
	const params = parseParams(exp);
	const db = await getDb();

	const all = await listEntitiesForRepo(db, ctx.repoPath);
	const under = all.filter(e =>
		e.artifact !== true
		// Drop stale entities under gitignored paths (out/, build/,
		// dist/, ...). Otherwise the naming-convention sample is
		// biased by compiled-output style (kebab-case files, minified
		// symbols) that doesn't reflect authored source.
		&& ctx.ignoreFilter.isIncluded(e.file)
		&& (e.file === params.path || e.file.startsWith(params.path.endsWith('/') ? params.path : params.path + '/')),
	);

	if (under.length === 0) {
		log.info(
			{ runId: ctx.runId, path: params.path },
			'convention.detect: no entities under path',
		);
		return {
			type:              'convention.detect',
			// The graph holds no entity under the path: empty, and complete.
			completeness:      graphCompleteness({ returned: 0 }),
			path:              params.path,
			namingSchema:      emptyNamingSchema(),
			baseClassIdioms:   [],
			privatePrefixCount: 0,
			dunderMethodCount:  0,
			totalEntities:     0,
			notFoundNote:      `No indexed entities under path "${params.path}".`,
		};
	}

	// (1) Naming schema
	const namingSchema = computeNamingSchema(under);

	// (2) Base-class idioms via INHERITS edges
	const idiomScan = await computeBaseClassIdioms(under, db, params.path);
	const baseClassIdioms = idiomScan.idioms;

	// (3) Private + dunder counts
	let privatePrefixCount = 0;
	let dunderMethodCount  = 0;
	for (const e of under) {
		if (e.kind !== 'function' && e.kind !== 'method') continue;
		if (isDunder(e.name)) dunderMethodCount++;
		else if (e.name.startsWith('_')) privatePrefixCount++;
	}

	log.info(
		{
			runId:        ctx.runId,
			path:         params.path,
			totalEntities: under.length,
			functions:    namingSchema.functions,
			classes:      namingSchema.classes,
			testFiles:    namingSchema.testFiles,
			idioms:       baseClassIdioms.length,
		},
		'convention.detect: complete',
	);

	// The counts and the naming schema are computed over every entity under the
	// path; the two cuts are on the base-class idioms.
	const limited: ReachedLimit[] = [];
	if (idiomScan.totalIdioms > MAX_BASE_CLASS_IDIOMS) {
		limited.push(reachedLimit('base-class idioms', MAX_BASE_CLASS_IDIOMS, 'overall', idiomScan.totalIdioms));
	}
	if (idiomScan.mostSubclasses > MAX_REPR_SUBCLASSES) {
		limited.push({
			what: 'named subclasses per base', limit: MAX_REPR_SUBCLASSES, scope: 'per-group',
			reason: `a base has ${idiomScan.mostSubclasses} subclasses and ${MAX_REPR_SUBCLASSES} are named for each; subclassCount holds the full number`,
		});
	}

	return {
		type:              'convention.detect',
		completeness:      graphCompleteness({
			returned: baseClassIdioms.length,
			found:    idiomScan.totalIdioms,
			limited,
			skipped:  idiomScan.noGraphNode.map(e => ({
				what:   `${e.name} (${e.file}:${e.startLine})`,
				reason: 'the class has no node in the stored graph, so its base classes were not read',
			})),
		}),
		path:              params.path,
		namingSchema,
		baseClassIdioms,
		privatePrefixCount,
		dunderMethodCount,
		totalEntities:     under.length,
		notFoundNote:      '',
	};
}

function classifyName(name: string): NamingCase {
	if (name.length < 2) return 'unknown';
	// Strip a single leading `_` (private convention) for
	// classification so `_helper_fn` still reads as snake_case.
	let s = name;
	if (s.startsWith('_') && !s.startsWith('__')) s = s.slice(1);
	// Dunder magic methods (Python) don't inform the schema either
	// way -- classify as unknown so they don't bias the sample.
	if (s.startsWith('__') && s.endsWith('__')) return 'unknown';

	if (s.includes('-')) return 'kebab-case';

	const hasUnderscore = s.includes('_');
	const hasUpper = /[A-Z]/.test(s);
	const startsUpper = /^[A-Z]/.test(s);
	if (hasUnderscore && !hasUpper) return 'snake_case';
	if (hasUnderscore && hasUpper) return 'mixed';
	if (!hasUnderscore && startsUpper) return 'PascalCase';
	if (!hasUnderscore && hasUpper && !startsUpper) return 'camelCase';
	if (!hasUnderscore && !hasUpper) return 'snake_case';  // all-lowercase counts as snake_case
	return 'unknown';
}

async function runDataModelTrace(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<DataModelTraceOutput> {
	const params = parseParams(exp);
	const db = await getDb();

	// (1) Resolve the target(s). Same policy as class.hierarchy: a name
	// may repeat across sub-packages, we surface all real definitions.
	const allTargets = (
		await findEntitiesByName(
			db,
			[params.entityName],
			{ repo: ctx.repoPath, kinds: TARGET_KINDS },
		)
	)
		.filter(e => e.artifact !== true)
		// Drop stale entities under gitignored paths so a compiled
		// twin of the source doesn't resolve alongside the authored
		// definition.
		.filter(e => ctx.ignoreFilter.isIncluded(e.file));
	const targets = allTargets.slice(0, MAX_TARGETS);

	if (targets.length === 0) {
		log.info(
			{ runId: ctx.runId, entityName: params.entityName },
			'data-model.trace: no target resolved',
		);
		return {
			type:         'data-model.trace',
			// The graph holds no class, interface or type of this name: empty, and complete.
			completeness: graphCompleteness({ returned: 0 }),
			subject:      params.entityName,
			nodes:        [],
			notFoundNote: `No class/interface/type named "${params.entityName}" found in repo "${ctx.repoPath}".`,
		};
	}

	// (2) Walk each target.
	const nodes: DataModelNode[] = [];
	const noGraphNode: Entity[] = [];
	// The largest count any ONE target had, for the two limits applied to each target.
	let mostFields  = 0;
	let mostCallers = 0;
	for (const t of targets) {
		const u64 = await entityU64ForId(t.id);
		if (u64 === undefined) { noGraphNode.push(t); continue; }

		const inheritsOut = await outNeighbors(u64, { kindFilter: ['INHERITS'] });
		const inheritsIn  = await inNeighbors(u64,  { kindFilter: ['INHERITS'] });
		const definesOut  = await outNeighbors(u64, { kindFilter: ['DEFINES'] });

		const extendsMap    = await entityIdsByU64s(inheritsOut);
		const subMap        = await entityIdsByU64s(inheritsIn);
		const fieldMap      = await entityIdsByU64s(definesOut);

		const extendsEnts = await hydrate(Array.from(extendsMap.values()));
		const subEnts     = await hydrate(Array.from(subMap.values()));
		const fieldEnts   = await hydrate(Array.from(fieldMap.values()));

		// Callers: 1-hop CALLS predecessors. Rank by file+line for
		// stability.
		const callers = await findCallers(db, t.id);
		callers.sort((a, b) => {
			if (a.file !== b.file) return a.file.localeCompare(b.file);
			return a.startLine - b.startLine;
		});

		const fieldLike = fieldEnts.filter(e => isFieldLike(e.kind));
		mostFields  = Math.max(mostFields, fieldLike.length);
		mostCallers = Math.max(mostCallers, callers.length);
		const fields: DataModelField[] = fieldLike
			.slice(0, MAX_FIELDS)
			.map(e => ({
				name: e.name,
				...(e.signature !== undefined && e.signature.length > 0 ? { type: e.signature } : {}),
			}));

		nodes.push({
			entityId:  t.id,
			name:      t.name,
			kind:      t.kind,
			file:      t.file,
			startLine: t.startLine,
			fields,
			extendsList: extendsEnts.map(e => ({
				entityId: e.id,
				name:     e.name,
				file:     e.file,
			})),
			subclasses: subEnts.map(e => ({
				entityId: e.id,
				name:     e.name,
				file:     e.file,
			})),
			topCallers: callers.slice(0, MAX_TOP_CALLERS).map(e => ({
				entityId: e.id,
				name:     e.name,
				file:     e.file,
				line:     e.startLine,
			})),
		});
	}

	log.info(
		{
			runId:      ctx.runId,
			entityName: params.entityName,
			targets:    targets.length,
			nodes:      nodes.length,
		},
		'data-model.trace: complete',
	);

	// One limit on the targets, and two applied to EACH target.
	const limited: ReachedLimit[] = [];
	if (allTargets.length > MAX_TARGETS) limited.push(reachedLimit('targets', MAX_TARGETS, 'overall', allTargets.length));
	if (mostFields > MAX_FIELDS) {
		limited.push({
			what: 'fields per target', limit: MAX_FIELDS, scope: 'per-group',
			reason: `a target has ${mostFields} fields and ${MAX_FIELDS} are kept for each`,
		});
	}
	if (mostCallers > MAX_TOP_CALLERS) {
		limited.push({
			what: 'callers per target', limit: MAX_TOP_CALLERS, scope: 'per-group',
			reason: `a target has ${mostCallers} callers and ${MAX_TOP_CALLERS} are kept for each`,
		});
	}

	return {
		type:         'data-model.trace',
		completeness: graphCompleteness({
			returned: nodes.length,
			found:    allTargets.length,
			limited,
			skipped:  noGraphNode.map(e => ({
				what:   `${e.name} (${e.file}:${e.startLine})`,
				reason: 'the type has no node in the stored graph, so its fields and callers were not read',
			})),
		}),
		subject:      params.entityName,
		nodes,
		notFoundNote: '',
	};

	async function hydrate(ids: readonly string[]): Promise<Entity[]> {
		if (ids.length === 0) return [];
		return getEntitiesByIds(db, [...ids]);
	}
}

exports.signature:
runDbConnectionsList(
	_exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbConnectionsListOutput>

exports.body:
async function runDbConnectionsList(
	_exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbConnectionsListOutput> {
	// A registry that cannot be read is a lookup that could not run: it throws,
	// and the executor reports it as failed. "No connections" is said only when
	// the registry was read and holds none.
	const pool = await acquire(ctx.repoPath);

	const list = pool.list();
	const connections: DbConnectionSummary[] = list.map(c => {
		const fam = c.family ?? familyOf(c.kind);
		return {
			id:     c.id,
			kind:   c.kind,
			family: (fam ?? 'file') as DbConnectionSummary['family'],
			label:  c.label ?? c.id,
			...(c.path !== undefined ? { path: c.path } : {}),
		};
	});

	log.info(
		{ runId: ctx.runId, repoPath: ctx.repoPath, count: connections.length },
		'db.connections.list: complete',
	);

	return {
		type:        'db.connections.list',
		completeness: buildCompleteness({ returned: connections.length, basis: 'data-source' }),
		connections,
		notFoundNote: connections.length === 0
			? `No data-driver connections registered for repo "${ctx.repoPath}".`
			: '',
	};
}

exports.signature:
runDbTableDescribe(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbTableDescribeOutput>

exports.body:
async function runDbTableDescribe(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbTableDescribeOutput> {
	const params = parseParams(exp);

	// The registry cannot be read, the connection cannot be opened, or the
	// describe call fails: the lookup could not run. Each throws, and the
	// executor reports the lookup as failed.
	const pool = await acquire(ctx.repoPath);
	const driver = await pool.acquire(params.connectionId);

	const family = driver.family;
	let columns: DbColumnSummary[] = [];
	let shapeSummary = '';
	let notFoundNote = '';
	// For the completeness record: this driver cannot describe (an expected
	// condition, named as skipped), or the key-value summary kept fewer
	// fields or keys than exist.
	let unsupported: string | undefined;
	let returned = 0;
	const limited: ReachedLimit[] = [];

	if (family === 'rdbms') {
		const schema = await (driver as RdbmsDriver).describe(params.target);
		columns = schema.columns.map(c => ({
			name:      c.name,
			type:      c.type,
			...(c.nullable   !== undefined ? { nullable:   c.nullable   } : {}),
			...(c.primaryKey !== undefined ? { primaryKey: c.primaryKey } : {}),
			...(c.foreignKey !== undefined ? { foreignKey: {
				table:  c.foreignKey.table,
				column: c.foreignKey.column,
			} } : {}),
		}));
	} else if (family === 'kv') {
		const kv = driver as KvDriver;
		if (kv.describeNamespace === undefined) {
			notFoundNote = `Driver kind '${driver.kind}' does not implement describeNamespace.`;
			unsupported = notFoundNote;
		} else {
			const desc = await kv.describeNamespace(params.target);
			shapeSummary = summariseKvDescription(desc);
			returned = Math.min(desc.fields.length, KV_SUMMARY_FIELDS);
			if (desc.fields.length > KV_SUMMARY_FIELDS) {
				limited.push(reachedLimit('fields', KV_SUMMARY_FIELDS, 'overall', desc.fields.length));
			}
			if (desc.sampleKeys.length > KV_SUMMARY_KEYS) {
				limited.push(reachedLimit('sample keys', KV_SUMMARY_KEYS, 'source', desc.sampleKeys.length));
			}
		}
	} else if (family === 'file') {
		const fd = driver as FileDriver;
		if (fd.describe === undefined) {
			notFoundNote = `Driver kind '${driver.kind}' does not implement describe.`;
			unsupported = notFoundNote;
		} else {
			const schema = await fd.describe(params.target);
			columns = schema.columns.map(c => ({
				name: c.name,
				type: c.type,
				...(c.nullable !== undefined ? { nullable: c.nullable } : {}),
			}));
		}
	}

	log.info(
		{
			runId:        ctx.runId,
			connectionId: params.connectionId,
			target:       params.target,
			family,
			columns:      columns.length,
		},
		'db.table.describe: complete',
	);

	if (family !== 'kv') returned = columns.length;
	const completeness = buildCompleteness({
		returned,
		limited,
		skipped: unsupported !== undefined ? [{ what: 'the description', reason: unsupported }] : [],
		basis:   'data-source',
		...(family === 'kv' ? { basisNote: 'a key-value namespace is described from a sample of its keys, not from every key' } : {}),
	});

	return {
		type:         'db.table.describe',
		completeness,
		connectionId: params.connectionId,
		target:       params.target,
		family,
		columns,
		shapeSummary,
		// A note that reports an unsupported description is in the record.
		notFoundNote: unsupported !== undefined ? '' : notFoundNote,
	};
}

exports.signature:
runDbTablesList(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbTablesListOutput>

exports.body:
async function runDbTablesList(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
	/** The connection pool's source; a test passes a stand-in. */
	acquire: typeof acquirePool = acquirePool,
): Promise<DbTablesListOutput> {
	const params = parseParams(exp);
	const limit = params.limit ?? DEFAULT_LIMIT;

	// The registry cannot be read, the connection cannot be opened, or the
	// listing call fails: the lookup could not run. Each throws, and the
	// executor reports the lookup as failed.
	const pool = await acquire(ctx.repoPath);
	const driver = await pool.acquire(params.connectionId);

	const family = driver.family;
	let tables: DbTableSummary[] = [];
	let truncated = false;
	let notFoundNote = '';
	// A driver that cannot list is an expected condition: the result is
	// returned and its record names the listing as skipped.
	let unsupported: string | undefined;

	if (family === 'rdbms') {
		const rdbms = driver as RdbmsDriver;
		if (rdbms.listTables === undefined) {
			notFoundNote = `Driver kind '${driver.kind}' does not implement listTables.`;
			unsupported = notFoundNote;
		} else {
			const opts: { readonly schema?: string; readonly limit?: number } =
				params.schema !== undefined ? { schema: params.schema, limit } : { limit };
			const listing = await rdbms.listTables(opts);
			tables = listing.tables.map(t => ({
				name:   t.name,
				...(t.schema !== undefined ? { schema: t.schema } : {}),
				kind:   t.kind,
				...(t.approxRowCount !== undefined ? { rowEstimate: t.approxRowCount } : {}),
			}));
			truncated = listing.truncated;
		}
	} else if (family === 'kv') {
		const kv = driver as KvDriver;
		if (kv.listNamespaces === undefined) {
			notFoundNote = `Driver kind '${driver.kind}' does not implement listNamespaces.`;
			unsupported = notFoundNote;
		} else {
			const listing = await kv.listNamespaces({ limit });
			tables = listing.namespaces.map(n => ({
				name: n.name,
				kind: n.kind ?? 'namespace',
				...(n.approxCount !== undefined ? { rowEstimate: n.approxCount } : {}),
			}));
			truncated = listing.truncated;
			if (!listing.supported) {
				notFoundNote = `Driver kind '${driver.kind}' reports listNamespaces not supported on this instance.`;
				unsupported = notFoundNote;
			}
		}
	} else {
		// family === 'file'; each connection is a single target (a
		// file or a directory-as-table). No cross-target listing --
		// surface the connection itself as the only "table".
		notFoundNote =
			`Connection '${params.connectionId}' is a file-family driver -- ` +
			`each connection is a single target and does not enumerate multiple tables.`;
	}

	log.info(
		{
			runId:        ctx.runId,
			connectionId: params.connectionId,
			family,
			tables:       tables.length,
			truncated,
		},
		'db.tables.list: complete',
	);

	const completeness = buildCompleteness({
		returned: tables.length,
		// The driver's own cut flag: it stopped at the limit it was given.
		limited:  truncated ? [reachedLimit(family === 'kv' ? 'namespaces' : 'tables', limit, 'overall', null)] : [],
		skipped:  unsupported !== undefined ? [{ what: 'the listing', reason: unsupported }] : [],
		basis:    'data-source',
		...(family === 'file' ? { basisNote: notFoundNote } : {}),
	});

	return {
		type:         'db.tables.list',
		completeness,
		connectionId: params.connectionId,
		family,
		tables,
		// A note that reports an unsupported listing is in the record;
		// the note left here explains an empty listing that is complete.
		notFoundNote: unsupported !== undefined ? '' : notFoundNote,
	};
}

exports.signature:
runSharedDocConstraintEnumerate(
	args: RunDocConstraintEnumerateArgs,
): Promise<DocConstraintEnumerateOutput>

exports.body:
async function runSharedDocConstraintEnumerate(
	args: RunDocConstraintEnumerateArgs,
): Promise<DocConstraintEnumerateOutput> {
	const prepared = await prepareDocConstraintEnumerate({
		subject:    args.subject,
		repoPath:   args.repoPath,
		db:         args.db,
		// Handed over explicitly: prepare is given a new object, built field by field.
		...(args.area !== undefined ? { area: args.area } : {}),
		...(args.maxSources !== undefined ? { maxSources: args.maxSources } : {}),
		...(args.runId !== undefined ? { runId: args.runId } : {}),
		...(args.logContext !== undefined ? { logContext: args.logContext } : {}),
	});
	if (prepared.kind === 'short-circuit') return prepared.shortCircuit;

	const cfg = loadAnalyzeConfig();
	const provider = args.provider ?? resolveRoleProvider('analyze.narrow', cfg);
	let raw: DocConstraintEnumerateLLMOutput;
	try {
		raw = await provider.completeStructured(
			[
				{ role: 'system', content: prepared.systemPrompt },
				{ role: 'user',   content: prepared.userTurn     },
			],
			DOC_CONSTRAINTS_SCHEMA,
			{
				maxAttempts:     cfg.shaper.structuredOutputRetries,
				disableThinking: true,
				maxTokens:       4_096,
			},
		);
	} catch (err) {
		// The sections were retrieved and the model that reads them could not be
		// called: the lookup could not run. What it had retrieved goes with the failure.
		throw new LookupFailedError(
			`doc.constraint.enumerate: the model call that reads the retrieved sections failed: ${errorMessage(err)}`,
			prepared.retrieved,
			{ cause: err },
		);
	}

	return finalizeDocConstraintEnumerate(prepared.prepared, raw, args.runId, args.logContext);
}

exports.signature:
prepareDocConstraintEnumerate(
	args: RunDocConstraintEnumerateArgs,
): Promise<DocConstraintEnumeratePrepareResult>

exports.body:
async function prepareDocConstraintEnumerate(
	args: RunDocConstraintEnumerateArgs,
): Promise<DocConstraintEnumeratePrepareResult> {
	const subject = args.subject.trim();
	if (subject.length === 0) {
		throw new Error('doc.constraint.enumerate: subject is required (non-empty string)');
	}
	const maxSources = args.maxSources !== undefined
		? Math.max(1, Math.min(30, args.maxSources))
		: 15;

	const report: DocsRetrievalReport = {};
	const sections = await retrieveDocSections({
		db:           args.db,
		report,
		query:        subject,
		closureRepos: [args.repoPath],
		...(args.area !== undefined ? { area: args.area } : {}),
		maxResults:   maxSources,
		kinds:        ['document', 'section'],
		previewChars: 0,
	});

	if (sections.length === 0) {
		log.info(
			{ runId: args.runId, subject, ctx: args.logContext },
			'doc.constraint.enumerate: no matching sections',
		);
		return {
			kind: 'short-circuit',
			shortCircuit: {
				type:                  'doc.constraint.enumerate',
				// The document index returned no section for the subject: empty, and complete.
				completeness:          buildCompleteness({ returned: 0, skipped: vectorPassSkipped(report.vectorPassSkipped), basis: 'doc-index', basisNote: DOC_INDEX_RULE }),
				subject,
				constraints:           [],
				notFoundNote:          `No doc sections in the retrieved corpus mention "${subject}".`,
				retrievedSectionCount: 0,
			},
		};
	}

	const hydrated: HydratedSection[] = [];
	const skipped: SkippedItem[] = vectorPassSkipped(report.vectorPassSkipped);
	const partlyRead: PartlyReadItem[] = [];
	const measurer = createItemMeasurer(args.db);
	for (const s of sections) {
		const entity = await getEntity(args.db, s.entityId);
		if (entity === null) {
			skipped.push({ what: `${s.file} § ${s.heading}`, reason: 'the section is no longer in the index' });
			continue;
		}
		const body = (entity.body ?? '').slice(0, SECTION_BODY_CHARS);
		hydrated.push({
			entityId: s.entityId,
			file:     s.file,
			heading:  s.heading,
			body,
		});
		// The model reads this much of the section; say so when the section is longer.
		const cut = await measurer.partlyRead(`${s.file} § ${s.heading}`, entity, body.length);
		if (cut !== undefined) partlyRead.push(cut);
	}

	const promptContent = loadPromptFile();
	const messages = buildMessages(promptContent, subject, hydrated);
	const systemMsg = messages[0]!.content as string;
	const userMsg   = messages[1]!.content as string;

	return {
		kind:         'narrow-llm',
		systemPrompt: systemMsg,
		userTurn:     userMsg,
		schema:       DOC_CONSTRAINTS_SCHEMA,
		retrieved:    hydrated.map(h => ({ source: `${h.file} § ${h.heading}`, content: h.body })),
		prepared: {
			subject,
			retrievedSectionCount: sections.length,
			validEntityIds:        hydrated.map(h => h.entityId),
			completenessFacts: {
				// The retrieval returns at most maxSources sections and does not say how many
				// matched. The limit is on what was read, not on what is returned from it.
				limited: sections.length >= maxSources
					? [reachedLimit('document sections', maxSources, 'source', null)]
					: [],
				skipped,
				partlyRead,
			},
		},
	};
}

function finalizeDocConstraintEnumerate(
	prepared:   DocConstraintEnumeratePrepared,
	raw:        DocConstraintEnumerateLLMOutput,
	runId?:     string,
	logContext?: string,
): DocConstraintEnumerateOutput {
	const validIds = new Set(prepared.validEntityIds);
	const filtered = raw.constraints.filter(c => validIds.has(c.sourceEntityId));

	log.info(
		{
			runId,
			ctx:       logContext,
			subject:   prepared.subject,
			retrieved: prepared.retrievedSectionCount,
			extracted: raw.constraints.length,
			surviving: filtered.length,
		},
		'doc.constraint.enumerate: extraction complete',
	);

	return {
		type:                  'doc.constraint.enumerate',
		completeness:          carriedCompleteness(filtered.length, 'doc-index', prepared.completenessFacts, DOC_INDEX_RULE),
		subject:               prepared.subject,
		constraints:           filtered,
		notFoundNote:          filtered.length === 0 ? (raw.notFoundNote || `No constraints on "${prepared.subject}" found in the retrieved sections.`) : '',
		retrievedSectionCount: prepared.retrievedSectionCount,
	};
}

async function runDocConstraintEnumerate(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<DocConstraintEnumerateOutput> {
	const params = parseExplorationParams(exp);
	const db = await getDb();
	return runSharedDocConstraintEnumerate({
		subject:    params.subject,
		repoPath:   ctx.repoPath,
		db,
		...(params.maxSources !== undefined ? { maxSources: params.maxSources } : {}),
		...(ctx.runId !== undefined ? { runId: ctx.runId } : {}),
		logContext: 'exploration',
	});
}

exports.signature:
runSharedDocDecisionTrace(
	args: RunDocDecisionTraceArgs,
): Promise<DocDecisionTraceOutput>

exports.body:
async function runSharedDocDecisionTrace(
	args: RunDocDecisionTraceArgs,
): Promise<DocDecisionTraceOutput> {
	const prepared = await prepareDocDecisionTrace({
		topic:      args.topic,
		repoPath:   args.repoPath,
		db:         args.db,
		// Handed over explicitly: prepare is given a new object, built field by field.
		...(args.area !== undefined ? { area: args.area } : {}),
		...(args.maxSources !== undefined ? { maxSources: args.maxSources } : {}),
		...(args.runId !== undefined ? { runId: args.runId } : {}),
		...(args.logContext !== undefined ? { logContext: args.logContext } : {}),
	});

	if (prepared.kind === 'short-circuit') return prepared.shortCircuit;

	// Fire the LLM call against the daemon-side shaperProvider.
	const cfg = loadAnalyzeConfig();
	const provider = args.provider ?? resolveRoleProvider('analyze.narrow', cfg);
	let raw: DocDecisionTraceLLMOutput;
	try {
		raw = await provider.completeStructured(
			[
				{ role: 'system', content: prepared.systemPrompt },
				{ role: 'user',   content: prepared.userTurn     },
			],
			DOC_DECISIONS_SCHEMA,
			{
				maxAttempts:     cfg.shaper.structuredOutputRetries,
				disableThinking: true,
				maxTokens:       4_096,
			},
		);
	} catch (err) {
		// The sections were retrieved and the model that reads them could not be
		// called: the lookup could not run. What it had retrieved goes with the failure.
		throw new LookupFailedError(
			`doc.decision.trace: the model call that reads the retrieved sections failed: ${errorMessage(err)}`,
			prepared.retrieved,
			{ cause: err },
		);
	}

	return finalizeDocDecisionTrace(prepared.prepared, raw, args.runId, args.logContext);
}

exports.signature:
prepareDocDecisionTrace(
	args: RunDocDecisionTraceArgs,
): Promise<DocDecisionTracePrepareResult>

exports.body:
async function prepareDocDecisionTrace(
	args: RunDocDecisionTraceArgs,
): Promise<DocDecisionTracePrepareResult> {
	const topic = args.topic.trim();
	if (topic.length === 0) {
		throw new Error('doc.decision.trace: topic is required (non-empty string)');
	}
	const maxSources = args.maxSources !== undefined
		? Math.max(1, Math.min(30, args.maxSources))
		: 15;

	// (1) Retrieve. V1 = repo-scoped (single-repo closure).
	const report: DocsRetrievalReport = {};
	const sections = await retrieveDocSections({
		db:           args.db,
		report,
		query:        topic,
		closureRepos: [args.repoPath],
		...(args.area !== undefined ? { area: args.area } : {}),
		maxResults:   maxSources,
		kinds:        ['document', 'section'],
		previewChars: 0,
	});

	if (sections.length === 0) {
		log.info(
			{ runId: args.runId, topic, ctx: args.logContext },
			'doc.decision.trace: no matching sections',
		);
		return {
			kind: 'short-circuit',
			shortCircuit: {
				type:                  'doc.decision.trace',
				// The document index returned no section for the topic: empty, and complete.
				completeness:          buildCompleteness({ returned: 0, skipped: vectorPassSkipped(report.vectorPassSkipped), basis: 'doc-index', basisNote: DOC_INDEX_RULE }),
				topic,
				decisions:             [],
				notFoundNote:          `No doc sections in the retrieved corpus mention "${topic}".`,
				retrievedSectionCount: 0,
			},
		};
	}

	// (2) Hydrate full bodies for the LLM extraction pass.
	const hydrated: HydratedSection[] = [];
	const skipped: SkippedItem[] = vectorPassSkipped(report.vectorPassSkipped);
	const partlyRead: PartlyReadItem[] = [];
	const measurer = createItemMeasurer(args.db);
	for (const s of sections) {
		const entity = await getEntity(args.db, s.entityId);
		if (entity === null) {
			skipped.push({ what: `${s.file} § ${s.heading}`, reason: 'the section is no longer in the index' });
			continue;
		}
		const body = (entity.body ?? '').slice(0, SECTION_BODY_CHARS);
		hydrated.push({
			entityId: s.entityId,
			file:     s.file,
			heading:  s.heading,
			body,
		});
		// The model reads this much of the section; say so when the section is longer.
		const cut = await measurer.partlyRead(`${s.file} § ${s.heading}`, entity, body.length);
		if (cut !== undefined) partlyRead.push(cut);
	}

	const promptContent = loadPromptFile();
	const messages = buildMessages(promptContent, topic, hydrated);
	const systemMsg = messages[0]!.content as string;
	const userMsg   = messages[1]!.content as string;

	return {
		kind:         'narrow-llm',
		systemPrompt: systemMsg,
		userTurn:     userMsg,
		schema:       DOC_DECISIONS_SCHEMA,
		retrieved:    hydrated.map(h => ({ source: `${h.file} § ${h.heading}`, content: h.body })),
		prepared: {
			topic,
			retrievedSectionCount: sections.length,
			validEntityIds:        hydrated.map(h => h.entityId),
			completenessFacts: {
				// The retrieval returns at most maxSources sections and does not say how many
				// matched. The limit is on what was read, not on what is returned from it.
				limited: sections.length >= maxSources
					? [reachedLimit('document sections', maxSources, 'source', null)]
					: [],
				skipped,
				partlyRead,
			},
		},
	};
}

function finalizeDocDecisionTrace(
	prepared:   DocDecisionTracePrepared,
	raw:        DocDecisionTraceLLMOutput,
	runId?:     string,
	logContext?: string,
): DocDecisionTraceOutput {
	// Faithfulness check: drop any decision whose sourceEntityId isn't
	// in the retrieved set. Prevents the LLM from inventing citations.
	const validIds = new Set(prepared.validEntityIds);
	const filtered = raw.decisions.filter(d => validIds.has(d.sourceEntityId));

	log.info(
		{
			runId,
			ctx:       logContext,
			topic:     prepared.topic,
			retrieved: prepared.retrievedSectionCount,
			extracted: raw.decisions.length,
			surviving: filtered.length,
		},
		'doc.decision.trace: extraction complete',
	);

	return {
		type:                  'doc.decision.trace',
		completeness:          carriedCompleteness(filtered.length, 'doc-index', prepared.completenessFacts, DOC_INDEX_RULE),
		topic:                 prepared.topic,
		decisions:             filtered,
		notFoundNote:          filtered.length === 0 ? (raw.notFoundNote || `No decisions on "${prepared.topic}" found in the retrieved sections.`) : '',
		retrievedSectionCount: prepared.retrievedSectionCount,
	};
}

async function runDocDecisionTrace(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<DocDecisionTraceOutput> {
	const params = parseExplorationParams(exp);
	const db = await getDb();
	return runSharedDocDecisionTrace({
		topic:      params.topic,
		repoPath:   ctx.repoPath,
		db,
		...(params.maxSources !== undefined ? { maxSources: params.maxSources } : {}),
		...(ctx.runId !== undefined ? { runId: ctx.runId } : {}),
		logContext: 'exploration',
	});
}

async function runDocMention(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<DocMentionOutput> {
	const params = parseParams(exp);
	const db = await getDb();

	const limit = params.limit ?? DEFAULT_LIMIT;
	const report: DocsRetrievalReport = {};
	const results = await retrieveDocSections({
		db,
		report,
		query:        params.subject,
		closureRepos: [ctx.repoPath],
		maxResults:   limit,
		minScore:     params.minScore ?? 0,
		previewChars: params.previewChars ?? DEFAULT_PREVIEW_CHARS,
		...(params.filenameHint !== undefined ? { filenameHint: params.filenameHint } : {}),
		...(params.kinds !== undefined ? { kinds: params.kinds } : {}),
	});

	const hits: DocMentionHit[] = results.map(r => ({
		entityId: r.entityId,
		file:     r.file,
		heading:  r.heading,
		kind:     r.kind,
		score:    Math.round(r.score * 1_000) / 1_000,
		...(r.bodyPreview !== undefined && r.bodyPreview.length > 0 ? { preview: r.bodyPreview } : {}),
	}));

	// A hit whose stored body the indexer cut was matched on that much of it.
	const measurer = createItemMeasurer(db);
	const partlyRead: PartlyReadItem[] = [];
	for (const r of results) {
		const entity = await getEntity(db, r.entityId);
		if (entity === null) continue;
		const m = await measurer.measure(entity);
		if (m.cutByIndexer) partlyRead.push(partlyReadEntry(`${r.file} § ${r.heading}`, m.storedChars, m));
	}

	log.info(
		{
			runId:    ctx.runId,
			subject:  params.subject,
			returned: hits.length,
			partlyRead: partlyRead.length,
		},
		'doc.mention: complete',
	);

	return {
		type:    'doc.mention',
		// The retrieval returns at most `limit` sections and does not say how many
		// matched, so a full page means more may exist.
		completeness: buildCompleteness({
			returned: hits.length,
			limited:  hits.length >= limit ? [reachedLimit('document sections', limit, 'overall', null)] : [],
			partlyRead,
			skipped:  vectorPassSkipped(report.vectorPassSkipped),
			basis:    'doc-index',
			basisNote: DOC_INDEX_RULE,
		}),
		subject: params.subject,
		hits,
	};
}

async function executePlan(args: ExecutePlanArgs): Promise<ExecutedPlan> {
	const start = Date.now();
	const results: ExecutedExploration[] = [];
	const outputsById = new Map<string, ExplorationOutput>();
	let totalCached = 0;

	// One filter per plan execution. Shared across every runner via
	// ExplorationRunnerContext so a single subprocess call to `git
	// ls-files` powers .gitignore-aware directory filtering across
	// the whole plan.
	const ignoreFilter = createRepoIgnoreFilter(args.repoPath);

	for (const originalExp of args.plan.explorations) {
		const runnerStart = Date.now();

		// Substitute placeholders like `$e1.hits[0].path` in params
		// against prior outputs BEFORE dispatch. Placeholders that
		// resolve to `undefined` (missing dep, bad accessor) or to
		// empty arrays (dependent output legitimately empty -- e.g.
		// a module.profile with no exports) return an
		// `unmetPrerequisites` marker so the executor skips the
		// runner cleanly instead of letting it throw a generic
		// "required" error. That keeps the Diagnostics section
		// readable: "prerequisite empty" vs "runtime failure".
		const { exp, unmetPrerequisites } = substitutePlaceholders(originalExp, outputsById);

		let output: ExplorationOutput = {
			type: 'failed',
			requested: exp.type,
			errorCode: 'not-executed',
			message: 'exploration was not executed (executor bug)',
		};
		let cached = false;

		const runner = RUNNERS[exp.type];
		if (runner === undefined) {
			output = {
				type: 'unsupported',
				requested: exp.type,
				reason: `V1 executor does not implement exploration type '${exp.type}'`,
			};
		} else if (unmetPrerequisites.length > 0) {
			// A placeholder resolved to nothing / to an empty array. The
			// decomposer emits many recipes with optional steps ("only
			// when profile.exports is non-empty") whose skip signal is
			// exactly this. Do NOT invoke the runner -- it would throw
			// a generic "required" error that the caller reads as a
			// framework bug rather than a designed skip.
			output = {
				type: 'failed',
				requested: exp.type,
				errorCode: 'prerequisite-empty',
				message:
					`skipped: placeholder(s) [${unmetPrerequisites.join(', ')}] ` +
					`resolved to empty/undefined against prior outputs. ` +
					`The dependent exploration produced no data for these accessors.`,
			};
		} else {
			const cacheable = !NON_CACHEABLE.has(exp.type);
			if (cacheable) {
				const hit = await getCachedExploration(
					args.repoPath, args.repoLastIndexedAtMs, exp,
				);
				if (hit !== null) {
					output = hit;
					cached = true;
					totalCached += 1;
				}
			}
			if (!cached) {
				try {
					const ctx: ExplorationRunnerContext = {
						runId:        args.runId,
						repoPath:     args.repoPath,
						closureRepos: args.closureRepos,
						readDep:      (id: string) => outputsById.get(id),
						ignoreFilter,
						scope:        args.scope,
					};
					output = await runner(exp, ctx);
					if (cacheable) {
						await putCachedExploration(
							args.repoPath, args.repoLastIndexedAtMs, exp, output,
						);
					}
				} catch (err) {
					log.warn(
						{ runId: args.runId, explorationId: exp.id, type: exp.type, err: errorMessage(err) },
						'exploration failed',
					);
					output = failedOutput(exp, err);
				}
			}
		}

		const elapsedMs = Date.now() - runnerStart;
		outputsById.set(exp.id, output);
		results.push({ exploration: exp, output, cached, elapsedMs });
	}

	const totalMs = Date.now() - start;
	log.info(
		{
			runId:       args.runId,
			answerType:  args.plan.answerType,
			total:       results.length,
			cached:      totalCached,
			failed:      results.filter(r => r.output.type === 'failed').length,
			unsupported: results.filter(r => r.output.type === 'unsupported').length,
			totalMs,
		},
		'plan executed',
	);

	return {
		plan:        args.plan,
		results,
		totalMs,
		totalCached,
	};
}

function getNarrowRunner(type: ExplorationType): NarrowRunnerEntry | undefined {
	return NARROW_RUNNERS[type];
}

exports.signature:
stepPlan(
	args: ExecutePlanArgs & {
		readonly resumeState?: StepPlanResumeState;
	},
): Promise<StepPlanResult>

exports.body:
async function stepPlan(
	args: ExecutePlanArgs & {
		readonly resumeState?: StepPlanResumeState;
	},
): Promise<StepPlanResult> {
	const runStart = Date.now();
	const outputsById = new Map<string, ExplorationOutput>();
	const results: ExecutedExploration[] = [];
	let totalCached = 0;
	let priorMs = 0;

	if (args.resumeState !== undefined) {
		for (const { id, output } of args.resumeState.outputs) {
			outputsById.set(id, output);
		}
		for (const r of args.resumeState.results) results.push(r);
		totalCached = args.resumeState.totalCached;
		priorMs = args.resumeState.totalMsSoFar;
	}

	const ignoreFilter = createRepoIgnoreFilter(args.repoPath);

	for (const originalExp of args.plan.explorations) {
		// Skip explorations that already have an output from a prior
		// turn (resume path).
		if (outputsById.has(originalExp.id)) continue;

		const runnerStart = Date.now();
		const { exp, unmetPrerequisites } = substitutePlaceholders(originalExp, outputsById);

		let output: ExplorationOutput = {
			type: 'failed',
			requested: exp.type,
			errorCode: 'not-executed',
			message: 'exploration was not executed (executor bug)',
		};
		let cached = false;

		const runner = RUNNERS[exp.type];
		if (runner === undefined) {
			output = {
				type: 'unsupported',
				requested: exp.type,
				reason: `V1 executor does not implement exploration type '${exp.type}'`,
			};
		} else if (unmetPrerequisites.length > 0) {
			output = {
				type: 'failed',
				requested: exp.type,
				errorCode: 'prerequisite-empty',
				message:
					`skipped: placeholder(s) [${unmetPrerequisites.join(', ')}] ` +
					`resolved to empty/undefined against prior outputs. ` +
					`The dependent exploration produced no data for these accessors.`,
			};
		} else if (NARROW_LLM_TYPES.has(exp.type) && NARROW_RUNNERS[exp.type] !== undefined) {
			// Narrow-LLM exploration: try cache first (same key as
			// executePlan), else prepare + pause.
			const hit = await getCachedExploration(
				args.repoPath, args.repoLastIndexedAtMs, exp,
			);
			if (hit !== null) {
				output = hit;
				cached = true;
				totalCached += 1;
			} else {
				const narrow = NARROW_RUNNERS[exp.type]!;
				const ctx: ExplorationRunnerContext = {
					runId:        args.runId,
					repoPath:     args.repoPath,
					closureRepos: args.closureRepos,
					readDep:      (id: string) => outputsById.get(id),
					ignoreFilter,
					scope:        args.scope,
				};
				// The same conversion as every other lookup: a prepare that throws is
				// a lookup that could not run. It becomes the failed output for THIS
				// lookup and the plan goes on; it does not abort the step call.
				let prep: NarrowPrepareResult | undefined;
				try {
					prep = await narrow.prepare(exp, ctx);
				} catch (err) {
					log.warn(
						{ runId: args.runId, explorationId: exp.id, type: exp.type, err: errorMessage(err) },
						'multi-turn exploration failed in prepare',
					);
					output = failedOutput(exp, err);   // never cached
				}
				if (prep === undefined) {
					// failed above: fall through to record the output
				} else if (prep.kind === 'short-circuit') {
					output = prep.shortCircuit;
					await putCachedExploration(
						args.repoPath, args.repoLastIndexedAtMs, exp, output,
					);
				} else {
					// PAUSE: return the prompt + schema, encode enough
					// resume state that the next call can pick up here.
					const elapsedForPause = Date.now() - runnerStart;
					return {
						kind:            'pending',
						explorationId:   exp.id,
						explorationType: exp.type,
						systemPrompt:    prep.systemPrompt,
						userTurn:        prep.userTurn,
						schema:          prep.schema,
						preparedBlob:    prep.prepared,
						resumeState: {
							results,
							outputs: [...outputsById.entries()].map(([id, out]) => ({ id, output: out })),
							totalCached,
							totalMsSoFar: priorMs + (Date.now() - runStart),
						},
						elapsedForPause,
					};
				}
			}
		} else {
			// Deterministic path -- identical to executePlan.
			const hit = await getCachedExploration(
				args.repoPath, args.repoLastIndexedAtMs, exp,
			);
			if (hit !== null) {
				output = hit;
				cached = true;
				totalCached += 1;
			} else {
				try {
					const ctx: ExplorationRunnerContext = {
						runId:        args.runId,
						repoPath:     args.repoPath,
						closureRepos: args.closureRepos,
						readDep:      (id: string) => outputsById.get(id),
						ignoreFilter,
						scope:        args.scope,
					};
					output = await runner(exp, ctx);
					await putCachedExploration(
						args.repoPath, args.repoLastIndexedAtMs, exp, output,
					);
				} catch (err) {
					log.warn(
						{ runId: args.runId, explorationId: exp.id, type: exp.type, err: errorMessage(err) },
						'multi-turn exploration failed',
					);
					output = failedOutput(exp, err);
				}
			}
		}

		const elapsedMs = Date.now() - runnerStart;
		outputsById.set(exp.id, output);
		results.push({ exploration: exp, output, cached, elapsedMs });
	}

	const totalMs = priorMs + (Date.now() - runStart);
	log.info(
		{
			runId:       args.runId,
			answerType:  args.plan.answerType,
			total:       results.length,
			cached:      totalCached,
			failed:      results.filter(r => r.output.type === 'failed').length,
			unsupported: results.filter(r => r.output.type === 'unsupported').length,
			totalMs,
		},
		'stepPlan: multi-turn plan executed',
	);

	return {
		kind: 'done',
		executed: {
			plan:        args.plan,
			results,
			totalMs,
			totalCached,
		},
	};
}

function failedOutput(exp: Exploration, err: unknown): FailedExplorationOutput {
	const partial = err instanceof LookupFailedError ? err.partial : [];
	return {
		type:      'failed',
		requested: exp.type,
		errorCode: classifyExplorationError(err),
		message:   errorMessage(err),
		...(partial.length > 0 ? { partial } : {}),
	};
}

function _overrideRunnerForTest(
	type:   ExplorationType,
	runner: ExplorationRunner | undefined,
): void {
	if (runner === undefined) delete RUNNERS[type];
	else RUNNERS[type] = runner;
}

function _getRunnersForTest(): Readonly<Partial<Record<ExplorationType, ExplorationRunner>>> {
	return RUNNERS;
}

exports.signature:
runFreeformProbe(
	exp:  Exploration,
	ctx:  ExplorationRunnerContext,
	/** The tool loop; a test passes a stand-in. */
	loop: typeof runShaperToolLoop = runShaperToolLoop,
): Promise<FreeformProbeOutput>

exports.body:
async function runFreeformProbe(
	exp:  Exploration,
	ctx:  ExplorationRunnerContext,
	/** The tool loop; a test passes a stand-in. */
	loop: typeof runShaperToolLoop = runShaperToolLoop,
): Promise<FreeformProbeOutput> {
	const params = parseParams(exp);
	const promptPath = legacyShaperPromptPathFor(params.shaperId);

	// The request's own scope, so the loop is told what the request
	// named (a file, an entity, a connection) and not just "the repo".
	// A caller that executes a plan on a bare repo path hands over no
	// scope: that is a workspace scope on the path.
	const scope: ResolvedScope = ctx.scope ?? {
		kind:       'workspace',
		value:      ctx.repoPath,
		repoPath:   null,
		lookupPath: ctx.repoPath,
	};

	// Reconstruct a run-mode input. The tool loop's buildMessages
	// carries the intent verbatim, so the scope reference here is what
	// the legacy prompt's scope-boundary rule keys off.
	const inputs: RunShapeInput = {
		intent: {
			target:    params.shaperId === 'generic' ? 'generic'
				: params.shaperId === 'code'   ? 'code'
				: params.shaperId === 'docs'   ? 'docs'
				: params.shaperId === 'data'   ? 'data'
				: 'infra',
			scope:    'M',
			focused:  true,
			focus:    params.purpose,
			scopeRef: { kind: scope.kind, value: scope.value },
			reasoning:
				'freeform.probe escape-hatch: intent fell outside every ' +
				'deterministic recipe; the decomposer emitted a single ' +
				'freeform.probe so the target\'s legacy tool loop can ' +
				'answer with its full read-only tool surface.',
		},
	};

	let rawBundle: Awaited<ReturnType<typeof runShaperToolLoop>>['rawBundle'];
	let toolCallCount = 0;
	try {
		const result = await loop({
			runId:          ctx.runId,
			shaperId:       params.shaperId,
			invocationMode: 'run',
			inputs,
			scope,
			promptPath,
		});
		rawBundle     = result.rawBundle;
		toolCallCount = result.toolCallCount;
	} catch (err) {
		if (err instanceof ShaperToolLoopExhausted) {
			// The search did not finish. That is a lookup that could not run, not
			// one that found nothing: it fails, and what its tool calls had
			// returned goes with the failure.
			log.warn(
				{ runId: ctx.runId, purpose: params.purpose, shaperId: params.shaperId, toolResults: err.toolResults.length },
				'freeform.probe: tool-loop exhausted',
			);
			throw new LookupFailedError(
				`freeform.probe: the search did not finish: ${err.message}. ` +
				'Refine the request or ask for a specific lookup.',
				err.toolResults,
				{ cause: err },
			);
		}
		// Anything else (LLM unavailable, schema unrecoverable, ...) --
		// bubble so the executor catches + emits a `failed` output.
		throw err;
	}

	log.info(
		{
			runId:         ctx.runId,
			purpose:       params.purpose,
			shaperId:      params.shaperId,
			toolCallCount,
		},
		'freeform.probe: complete',
	);

	return {
		type:      'freeform.probe',
		// The answer rests on a search a model chose, call by call. Nothing shows
		// that the search covered everything relevant, so it is never complete.
		completeness: buildCompleteness({
			returned: 1, basis: 'model-directed', notEstablished: true,
			basisNote: `a model chose what to search, in ${toolCallCount} tool call${toolCallCount === 1 ? '' : 's'}; what it did not look at is not known`,
		}),
		purpose:   params.purpose,
		shaperId:  params.shaperId,
		rawBundle,
		toolCallCount,
	};
}

async function runImportGraph(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<ImportGraphOutput> {
	const { path, topK } = parseParams(exp);

	const db = await getDb();
	const allEntities = await listEntitiesForRepo(db, ctx.repoPath);

	// Collect File entities WITHIN `path`. Treat `path` as either a
	// directory prefix or an exact file path. Drop stale entities
	// under gitignored paths (out/, build/, dist/, ...) so we don't
	// build the graph across the compiled twin of the source tree.
	const inScopeFiles: Entity[] = [];
	const pathWithSep = path.endsWith(sep) ? path : path + sep;
	for (const e of allEntities) {
		if (e.kind !== 'file') continue;
		if (!ctx.ignoreFilter.isIncluded(e.file)) continue;
		if (e.file === path || e.file.startsWith(pathWithSep)) {
			inScopeFiles.push(e);
		}
	}

	if (inScopeFiles.length === 0) {
		log.info({ runId: ctx.runId, path }, 'import.graph: no in-scope files');
		return {
			type: 'import.graph',
			// No file of the graph lies under the path: an empty result, and a complete one.
			completeness: graphCompleteness({ returned: 0 }),
			summary: {
				target: path,
				topImporters:   [],
				topImportees:   [],
				totalInDegree:  0,
				totalOutDegree: 0,
			},
		};
	}

	// For each in-scope file, count inbound + outbound IMPORTS edges
	// crossing the module boundary (i.e. the neighbour is a file
	// OUTSIDE `path`).
	const importerCount = new Map<string, number>();  // otherFile -> edges
	const importeeCount = new Map<string, number>();  // otherFile -> edges
	let totalIn  = 0;
	let totalOut = 0;

	const inScopePaths = new Set(inScopeFiles.map(e => e.file));
	const noGraphNode: string[] = [];

	for (const f of inScopeFiles) {
		const u64 = await entityU64ForId(f.id);
		if (u64 === undefined) { noGraphNode.push(f.file); continue; }

		// Inbound: who imports THIS file (files outside our scope).
		const importers = await inNeighbors(u64, { kindFilter: ['IMPORTS'] });
		const importerIdMap = await entityIdsByU64s(importers);
		const importerIds: string[] = [];
		for (const u of importers) {
			const sid = importerIdMap.get(u);
			if (sid !== undefined) importerIds.push(sid);
		}
		const importerEntities = await getEntitiesByIds(db, importerIds);
		for (const ie of importerEntities) {
			if (ie.repo !== ctx.repoPath) continue;
			if (!ctx.ignoreFilter.isIncluded(ie.file)) continue;
			if (inScopePaths.has(ie.file)) continue;
			importerCount.set(ie.file, (importerCount.get(ie.file) ?? 0) + 1);
			totalIn += 1;
		}

		// Outbound: what THIS file imports (files outside our scope).
		const importees = await outNeighbors(u64, { kindFilter: ['IMPORTS'] });
		const importeeIdMap = await entityIdsByU64s(importees);
		const importeeIds: string[] = [];
		for (const u of importees) {
			const sid = importeeIdMap.get(u);
			if (sid !== undefined) importeeIds.push(sid);
		}
		const importeeEntities = await getEntitiesByIds(db, importeeIds);
		for (const ie of importeeEntities) {
			if (ie.repo !== ctx.repoPath) continue;
			if (!ctx.ignoreFilter.isIncluded(ie.file)) continue;
			if (inScopePaths.has(ie.file)) continue;
			importeeCount.set(ie.file, (importeeCount.get(ie.file) ?? 0) + 1);
			totalOut += 1;
		}
	}

	const k = topK ?? DEFAULT_TOP_K;
	const topImporters = Array.from(importerCount.entries())
		.map(([file, edges]) => ({ file, edges }))
		.sort((a, b) => b.edges - a.edges)
		.slice(0, k);
	const topImportees = Array.from(importeeCount.entries())
		.map(([file, edges]) => ({ file, edges }))
		.sort((a, b) => b.edges - a.edges)
		.slice(0, k);

	// Two lists, each cut to the same number: a limit on each, not on their sum.
	const limited: ReachedLimit[] = [];
	if (importerCount.size > k) limited.push(reachedLimit('importing files', k, 'per-group', importerCount.size));
	if (importeeCount.size > k) limited.push(reachedLimit('imported files', k, 'per-group', importeeCount.size));
	const completeness = graphCompleteness({
		returned: topImporters.length + topImportees.length,
		found:    importerCount.size + importeeCount.size,
		limited,
		skipped:  noGraphNode.map(file => ({ what: file, reason: 'the file has no node in the stored graph, so its imports were not read' })),
	});

	const summary: ImportGraphSummary = {
		target:         path,
		topImporters,
		topImportees,
		totalInDegree:  totalIn,
		totalOutDegree: totalOut,
	};

	log.info(
		{
			runId:         ctx.runId,
			path,
			inScopeFiles:  inScopeFiles.length,
			totalIn,
			totalOut,
			topImporters:  topImporters.length,
			topImportees:  topImportees.length,
		},
		'import.graph: complete',
	);

	return { type: 'import.graph', completeness, summary };
}

function summarisedFrom(
	measurer:      ItemMeasurer,
	entity:        StoredItem,
	summariserCut: number,
): Promise<PartlyReadItem | undefined> {
	const stored = entity.body.endsWith(INDEXER_CUT_MARKER) ? entity.body.length - INDEXER_CUT_MARKER.length : entity.body.length;
	return measurer.partlyRead(entity.file, entity, Math.min(summariserCut, stored));
}

function createItemMeasurer(db: DbClient, entities?: readonly Entity[]): ItemMeasurer {
	const hashByFile = new Map<string, string | undefined>();
	if (entities !== undefined) {
		for (const e of entities) {
			if (e.kind === 'file' && !hashByFile.has(e.file)) hashByFile.set(e.file, e.hash);
		}
	}

	async function recordedHash(entity: StoredItem): Promise<string | undefined> {
		const file = entity.file;
		if (hashByFile.has(file)) return hashByFile.get(file);
		// Every parser keys a file's own entity the same way: (repo, file, 'file', file).
		const fileEntity = await getEntity(db, makeEntityId(entity.repo, file, 'file', file));
		const hash = fileEntity?.hash;
		hashByFile.set(file, hash);
		return hash;
	}

	async function measure(entity: StoredItem): Promise<ItemMeasure> {
		return measureItem(entity, { recordedFileHash: await recordedHash(entity) });
	}

	return {
		measure,
		async partlyRead(what, entity, readChars) {
			const m = await measure(entity);
			const longer = readChars < m.storedChars || m.cutByIndexer
				|| (m.totalChars !== null && m.totalChars > readChars);
			return longer ? partlyReadEntry(what, readChars, m) : undefined;
		},
	};
}

class LookupFailedError extends Error {
	readonly partial: readonly PartialFinding[];

	constructor(message: string, partial: readonly PartialFinding[] = [], options?: { readonly cause?: unknown }) {
		super(message, options);
		this.name = 'LookupFailedError';
		this.partial = partial;
	}
}

function errorMessage(err: unknown): string {
	return err instanceof Error ? err.message : String(err);
}

async function runManifestsLocate(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<ManifestsLocateOutput> {
	const params = parseParams(exp);
	const db = await getDb();

	const all = await listEntitiesForRepo(db, ctx.repoPath);

	const familyFilter = params.families !== undefined
		? new Set(params.families)
		: null;

	const topK = params.topK ?? DEFAULT_TOP_K;
	// Manifests that pass every filter, counted past the limit as well.
	let found = 0;
	const measurer = createItemMeasurer(db, all);
	const partlyRead: PartlyReadItem[] = [];
	const skipped: SkippedItem[] = [];
	// A file has several entities (the file itself, the document, its
	// sections). The one whose stored body the indexer cut says the index
	// holds only part of the file, whichever entity the loop below meets first.
	const cutEntityByFile = new Map<string, Entity>();
	for (const e of all) {
		if (e.artifact === true && e.body.endsWith(INDEXER_CUT_MARKER) && WHOLE_FILE_ENTITY_KINDS.has(e.kind) && !cutEntityByFile.has(e.file)) {
			cutEntityByFile.set(e.file, e);
		}
	}
	const seen = new Set<string>();
	const hits: ManifestHit[] = [];
	const familyCounts: Record<ManifestFamily, number> = {
		kubernetes: 0, helm: 0, terraform: 0, docker: 0, ci: 0, other: 0,
	};

	for (const e of all) {
		if (e.artifact !== true) continue;
		if (!isManifestCandidate(e)) continue;
		// Drop stale entities under gitignored paths so a docker-
		// compose.yml copied into out/ doesn't double-count.
		if (!ctx.ignoreFilter.isIncluded(e.file)) continue;
		if (seen.has(e.file)) continue;
		seen.add(e.file);

		const family = classifyFamily(e.file);
		if (familyFilter !== null && !familyFilter.has(family)) continue;

		found += 1;
		// Past the limit a manifest is counted, so the result can say how many
		// exist; `hits` and `families` describe the ones returned, as before.
		if (hits.length >= topK) continue;

		familyCounts[family] += 1;

		// Prefer the real kind parsed from the indexed manifest body; fall back
		// to the filename heuristic when the body is empty / unparseable.
		const resourceKind = resourceKindFromBody(e.file, family, e.body)
			?? inferResourceKind(e.file, family);
		// Expected: a stored body that is not valid YAML (a template, or a body
		// the indexer cut mid-document). The kind is then the file name's guess.
		if (manifestBodyUnparsable(family, e.body)) {
			skipped.push({ what: e.file, reason: "its stored content is not valid YAML, so its kind is a guess from the file name" });
		}
		// The kind is read from the STORED body. A manifest the indexer cut was
		// read in part, so its kind may be the file name's guess.
		const cutEntity = cutEntityByFile.get(e.file);
		if (cutEntity !== undefined) {
			const m = await measurer.measure(cutEntity);
			partlyRead.push(partlyReadEntry(e.file, m.storedChars, m));
		}

		hits.push({
			file:   e.file,
			family,
			...(resourceKind !== undefined ? { resourceKind } : {}),
			name:     basename(e.file),
			entityId: e.id,
		});
	}

	log.info(
		{
			runId:  ctx.runId,
			total:  hits.length,
			families: familyCounts,
		},
		'manifests.locate: complete',
	);

	return {
		type:      'manifests.locate',
		completeness: graphCompleteness({
			returned: hits.length,
			found,
			limited:  found > topK ? [reachedLimit('manifests', topK, 'overall', found)] : [],
			partlyRead,
			skipped,
		}),
		hits,
		families:  familyCounts,
		notFoundNote: hits.length === 0
			? `No infra manifests indexed under "${ctx.repoPath}"${
				familyFilter !== null ? ` matching families [${Array.from(familyFilter).join(', ')}]` : ''
			}.`
			: '',
	};
}

function classifyFamily(file: string): ManifestFamily {
	const bn = basename(file);
	const ext = extname(file).toLowerCase();
	if (bn.startsWith('Dockerfile')) return 'docker';
	if (bn === 'docker-compose.yml' || bn === 'docker-compose.yaml') return 'docker';
	if (ext === '.tf' || ext === '.tfvars' || ext === '.hcl') return 'terraform';
	if (isCIPath(file)) return 'ci';
	if (isHelmPath(file)) return 'helm';
	if (isK8sPath(file)) return 'kubernetes';
	return 'other';
}

function isK8sPath(file: string): boolean {
	return /(^|\/)(k8s|kubernetes|manifests|deploy|deployments)\//i.test(file);
}

function isHelmPath(file: string): boolean {
	if (basename(file) === 'Chart.yaml') return true;
	if (basename(file) === 'values.yaml') return true;
	return /(^|\/)helm\//i.test(file) || /(^|\/)charts?\//i.test(file);
}

function isCIPath(file: string): boolean {
	if (/(^|\/)\.github\/workflows\//.test(file)) return true;
	if (basename(file) === '.gitlab-ci.yml') return true;
	if (basename(file) === '.gitlab-ci.yaml') return true;
	if (basename(file) === 'Jenkinsfile') return true;
	if (basename(file) === 'azure-pipelines.yml') return true;
	if (basename(file) === 'bitbucket-pipelines.yml') return true;
	if (basename(file) === '.circleci' || file.includes('/.circleci/')) return true;
	if (/(^|\/)\.buildkite\//.test(file)) return true;
	return false;
}

function inferResourceKind(file: string, family: ManifestFamily): string | undefined {
	if (family !== 'kubernetes' && family !== 'helm') return undefined;
	const stem = basename(file, extname(file)).toLowerCase();
	const candidates = [
		'deployment', 'statefulset', 'daemonset', 'replicaset', 'pod',
		'service', 'ingress', 'configmap', 'secret',
		'serviceaccount', 'role', 'rolebinding', 'clusterrole', 'clusterrolebinding',
		'namespace', 'networkpolicy', 'poddisruptionbudget',
		'horizontalpodautoscaler', 'cronjob', 'job',
	];
	for (const k of candidates) {
		if (stem.endsWith(k) || stem.startsWith(k) || stem.includes(`-${k}`)) {
			return capitalise(k);
		}
	}
	return undefined;
}

function resourceKindFromBody(file: string, family: ManifestFamily, body: string): string | undefined {
	if (body.length === 0) return undefined;
	if (family !== 'kubernetes' && family !== 'helm') return undefined;

	let docs: unknown[];
	try {
		docs = loadAll(body);
	} catch {
		return undefined;
	}

	if (family === 'helm') {
		if (basename(file) !== 'Chart.yaml') return undefined;
		const chart = docs.find(d => d !== null && typeof d === 'object') as Record<string, unknown> | undefined;
		const name = chart?.['name'];
		return typeof name === 'string' ? name : undefined;
	}

	// kubernetes: first non-null object document's string `kind`.
	for (const d of docs) {
		if (d === null || typeof d !== 'object') continue;
		const kind = (d as Record<string, unknown>)['kind'];
		if (typeof kind === 'string') return kind;
	}
	return undefined;
}

function manifestBodyUnparsable(family: ManifestFamily, body: string): boolean {
	if (body.length === 0) return false;
	if (family !== 'kubernetes' && family !== 'helm') return false;
	try { loadAll(body); return false; }
	catch { return true; }
}

async function runModuleProfile(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<ModuleProfileOutput> {
	const { path } = parseParams(exp);

	// Distinguish dir vs file up front. If the caller passed a file
	// path, produce a file-shaped profile; otherwise walk it as a
	// directory.
	let stat;
	try { stat = statSync(path); }
	catch (err) {
		throw new Error(`module.profile: cannot stat '${path}': ${(err as Error).message}`);
	}

	const db = await getDb();
	const entities = await listEntitiesForRepo(db, ctx.repoPath);

	// Entry points are looked for in the first 4,096 characters of a file's
	// stored body. A longer file in which none was found was read in part.
	const measurer = createItemMeasurer(db, entities);
	const partlyRead: PartlyReadItem[] = [];

	if (stat.isFile()) {
		const profile = await profileFile(path, entities, measurer, partlyRead);
		log.info(
			{ runId: ctx.runId, path, kind: 'file', entityCount: profile.entityCount },
			'module.profile: file profiled',
		);
		return {
			type: 'module.profile',
			completeness: buildCompleteness({ returned: 1, partlyRead, basis: 'filesystem', basisNote: ENTRYPOINT_RULE }),
			profile,
		};
	}

	const skipped: SkippedItem[] = [];
	const profile = await profileDir(path, entities, ctx.ignoreFilter, measurer, partlyRead, skipped);
	log.info(
		{
			runId:       ctx.runId,
			path,
			kind:        'dir',
			subdirs:     profile.subdirs.length,
			files:       profile.filesInDir.length,
			exports:     profile.exports.length,
			entrypoints: profile.entrypoints.length,
			entityCount: profile.entityCount,
		},
		'module.profile: dir profiled',
	);
	return {
		type: 'module.profile',
		// Every immediate child of the directory is listed; nothing is cut by count.
		completeness: buildCompleteness({
			returned: profile.subdirs.length + profile.filesInDir.length,
			partlyRead,
			skipped,
			basis:    'filesystem',
			basisNote: ENTRYPOINT_RULE,
		}),
		profile,
	};
}

async function runSearchText(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<SearchTextOutput> {
	const params = parseParams(exp);

	// Scope check: if the caller passed an explicit `path`, it must
	// be inside ctx.repoPath. Prevents a stray decomposer plan from
	// grepping outside the closure.
	const root = params.path !== undefined
		? resolveScopedPath(params.path, ctx.repoPath)
		: ctx.repoPath;

	// At least 1, as the search itself enforces: a topK below 1 floors to 0.
	const limit = Math.max(1, params.topK ?? DEFAULT_TOP_K);
	// A search that could not run throws, and the executor reports the lookup as
	// failed. It does not return an empty result: that would read as "nothing matches".
	const data = await runGrepSearch({
		pattern:         params.pattern,
		root,
		...(params.glob !== undefined ? { glob: params.glob } : {}),
		caseInsensitive: params.caseInsensitive === true,
		limit,
	});

	const hits: SearchTextHit[] = data.hits.map(h => ({
		// Grep returns paths relative to `root`; make absolute so
		// citations survive without a per-hit root reminder.
		file: h.path.startsWith('/') ? h.path : `${root}/${h.path}`,
		line: h.line,
		text: h.text,
	}));

	log.info(
		{
			runId:           ctx.runId,
			pattern:         params.pattern,
			glob:            params.glob ?? '(none)',
			caseInsensitive: params.caseInsensitive === true,
			root,
			backend:         data.usedRipgrep ? 'ripgrep' : 'node',
			hits:            hits.length,
			truncated:       data.truncated,
		},
		'search.text: complete',
	);

	return {
		type:      'search.text',
		completeness: textSearchCompleteness(data, limit),
		pattern:   params.pattern,
		hits,
		backend:   data.usedRipgrep ? 'ripgrep' : 'node',
		root:      data.root,
	};
}

async function runSymbolLocate(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<SymbolLocateOutput> {
	const params = parseParams(exp);
	const db = await getDb();

	// Exact match first -- indexed by name, O(K) where K = matches.
	let matched: Entity[] = [];
	if (params.matchMode === 'exact') {
		matched = await findEntitiesByName(db, params.names, {
			repo:  ctx.repoPath,
			kinds: params.kinds!,
		});
	}

	// Substring fallback (or the requested match mode). Walks every
	// entity in the repo + does a case-insensitive substring match.
	// Not cheap on a large repo (~50-100k entities) but still <1s.
	if (matched.length === 0 || params.matchMode === 'substring') {
		const all = await listEntitiesForRepo(db, ctx.repoPath);
		const lcNames = params.names.map(n => n.toLowerCase());
		const kindSet = new Set<string>(params.kinds!);
		const substringMatches: Entity[] = [];
		for (const e of all) {
			if (!kindSet.has(e.kind)) continue;
			if (e.artifact === true) continue;
			const lcName = e.name.toLowerCase();
			for (const q of lcNames) {
				if (lcName.includes(q)) {
					substringMatches.push(e);
					break;
				}
			}
		}
		if (matched.length === 0) matched = substringMatches;
		else matched = mergeUnique(matched, substringMatches);
	}

	// Drop stale entities under gitignored paths (out/, build/, dist/,
	// ...). Otherwise a symbol defined in src/ shows up twice -- once
	// from source, once from its compiled JS twin -- and the outer LLM
	// cites the compiled file as if it were canonical.
	matched = matched.filter(e => ctx.ignoreFilter.isIncluded(e.file));

	// Cap + sort deterministically (by file:line for stable output).
	matched.sort((a, b) => {
		if (a.file !== b.file) return a.file.localeCompare(b.file);
		return a.startLine - b.startLine;
	});
	const limit = params.limit ?? DEFAULT_LIMIT;
	const capped = matched.slice(0, limit);

	const hits: SymbolHit[] = capped.map(e => ({
		entityId:  e.id,
		name:      e.name,
		kind:      e.kind,
		file:      e.file,
		startLine: e.startLine,
		endLine:   e.endLine,
		...(e.signature !== undefined && e.signature.length > 0 ? { signature: e.signature } : {}),
	}));

	log.info(
		{
			runId:       ctx.runId,
			names:       params.names,
			matchMode:   params.matchMode,
			returned:    hits.length,
			totalMatched: matched.length,
		},
		'symbol.locate: complete',
	);

	return {
		type:  'symbol.locate',
		completeness: graphCompleteness({
			returned: hits.length,
			found:    matched.length,
			limited:  matched.length > limit ? [reachedLimit('symbols', limit, 'overall', matched.length)] : [],
		}),
		names: params.names,
		hits,
	};
}

async function runTestLocate(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<TestLocateOutput> {
	const params = parseParams(exp);
	const db = await getDb();

	// Split subject into distinctive fragments. Drop 2-char and
	// generic fragments so a subject like "the matching module" doesn't
	// pull `the`, `module` (already noise for test-file matching).
	const fragments = tokenise(params.subject);
	if (fragments.length === 0) {
		return {
			type:         'test.locate',
			// No query could be formed, so nothing was searched: not a search that found nothing.
			completeness: buildCompleteness({
				returned: 0, basis: 'graph', notEstablished: true,
				basisNote: `${GRAPH_BASIS_NOTE}. The subject held no distinctive word to match, so no search was made`,
			}),
			subject:      params.subject,
			hits:         [],
			notFoundNote: `Subject "${params.subject}" contained no distinctive fragments to match against test entities.`,
		};
	}

	const all = await listEntitiesForRepo(db, ctx.repoPath);

	const hitsByFile = new Map<string, TestLocateHit>();
	const entityHits: TestLocateHit[] = [];

	for (const e of all) {
		if (e.artifact === true) continue;
		// Drop stale entities under gitignored paths so a compiled
		// twin doesn't double-count as a matching test.
		if (!ctx.ignoreFilter.isIncluded(e.file)) continue;
		const inTestPath = TEST_PATH_RX.test(e.file);
		const stemIsTest = TEST_STEM_RX.test(basename(e.file, extname(e.file)));

		// Path filter: entity file MUST live in a test path (dir or
		// stem-shaped). Otherwise this is production code, not a test.
		if (!inTestPath && !stemIsTest) continue;

		// Path-level hit (file shape names the subject)
		const stem = basename(e.file, extname(e.file)).toLowerCase();
		const fileMatches = fragments.some(f => stem.includes(f));

		// Entity-level hit (test function / class names the subject)
		const nameMatches = TESTABLE_KINDS.includes(e.kind)
			&& fragments.some(f => e.name.toLowerCase().includes(f));

		if (nameMatches) {
			entityHits.push({
				entityId:  e.id,
				name:      e.name,
				kind:      e.kind as TestLocateHit['kind'],
				file:      e.file,
				startLine: e.startLine,
			});
		}
		if (fileMatches && !hitsByFile.has(e.file)) {
			hitsByFile.set(e.file, {
				name: basename(e.file),
				kind: 'file',
				file: e.file,
			});
		}
	}

	// Combine: entity hits first (they're more specific), then
	// file-level hits, deduped by (file, entityId).
	const topK = params.topK ?? DEFAULT_TOP_K;
	const combined: TestLocateHit[] = [];
	const seen = new Set<string>();
	for (const list of [entityHits, Array.from(hitsByFile.values())]) {
		for (const h of list) {
			const key = `${h.file}::${h.entityId ?? h.name}`;
			if (seen.has(key)) continue;
			seen.add(key);
			// Past the limit the hit is still counted, so the result can say how many exist.
			if (combined.length < topK) combined.push(h);
		}
	}
	const found = seen.size;

	log.info(
		{
			runId:      ctx.runId,
			subject:    params.subject,
			fragments,
			returned:   combined.length,
			entityHits: entityHits.length,
			fileHits:   hitsByFile.size,
		},
		'test.locate: complete',
	);

	return {
		type:         'test.locate',
		completeness: graphCompleteness({
			returned: combined.length,
			found,
			limited:  found > topK ? [reachedLimit('tests', topK, 'overall', found)] : [],
		}),
		subject:      params.subject,
		hits:         combined,
		notFoundNote: combined.length === 0
			? `No test entities or files under "${ctx.repoPath}" matched fragments [${fragments.join(', ')}] of "${params.subject}".`
			: '',
	};
}

async function runUsageExample(
	exp: Exploration,
	ctx: ExplorationRunnerContext,
): Promise<UsageExampleOutput> {
	const params = parseParams(exp);
	const db = await getDb();

	// (1) Resolve the target entity. If entityId is given, use it
	// verbatim. Otherwise resolve symbolName via findEntitiesByName;
	// if that returns multiple candidates, pick the top hit but log
	// the ambiguity so the synthesizer knows.
	const targetKinds = params.kinds ?? DEFAULT_TARGET_KINDS;
	let target: Entity | undefined;
	let ambiguousCandidates = 0;
	if (params.entityId !== undefined) {
		const row = await getEntity(db, params.entityId);
		if (row !== null) target = row;
	} else {
		const rows = (
			await findEntitiesByName(
				db,
				[params.symbolName!],
				{ repo: ctx.repoPath, kinds: targetKinds },
			)
		)
			// Drop stale entities under gitignored paths so the compiled
			// twin doesn't hijack the usage-example resolution.
			.filter(r => ctx.ignoreFilter.isIncluded(r.file));
		ambiguousCandidates = rows.length;
		if (rows.length > 0) {
			// Prefer the non-artefact / non-test-path candidate.
			const preferred = rows.find(r => r.artifact !== true
				&& !/(^|\/)(tests?|__tests__|test|spec|specs)\//i.test(r.file));
			target = preferred ?? rows[0]!;
		}
	}

	if (target === undefined) {
		log.info(
			{
				runId:      ctx.runId,
				symbolName: params.symbolName,
				entityId:   params.entityId,
				ambiguous:  ambiguousCandidates,
			},
			'usage.example: target not resolved; returning empty output',
		);
		return {
			type:         'usage.example',
			// Nothing in the graph carries this name or id: an empty result, and a complete one.
			completeness: graphCompleteness({ returned: 0 }),
			subject:      params.symbolName ?? params.entityId ?? '',
			callers:      [],
		};
	}

	// (2) 1-hop callers via CALLS predecessors.
	const callers = await findCallers(db, target.id);

	// (3) Cap deterministically -- rank by file+line so results are
	// reproducible across runs (same input, same output).
	callers.sort((a, b) => {
		if (a.file !== b.file) return a.file.localeCompare(b.file);
		return a.startLine - b.startLine;
	});
	const topK = params.topK ?? DEFAULT_TOP_K;
	const capped = callers.slice(0, topK);

	const hits: UsageExampleHit[] = capped.map(e => ({
		entityId:  e.id,
		name:      e.name,
		kind:      e.kind,
		file:      e.file,
		startLine: e.startLine,
		endLine:   e.endLine,
		...(e.signature !== undefined && e.signature.length > 0 ? { signature: e.signature } : {}),
	}));

	log.info(
		{
			runId:         ctx.runId,
			subject:       params.symbolName ?? params.entityId,
			targetId:      target.id,
			totalCallers:  callers.length,
			returned:      hits.length,
			ambiguous:     ambiguousCandidates,
		},
		'usage.example: complete',
	);

	return {
		type:            'usage.example',
		completeness: graphCompleteness({
			returned: hits.length,
			found:    callers.length,
			limited:  callers.length > topK ? [reachedLimit('callers', topK, 'overall', callers.length)] : [],
			// Several entities carry the name and the callers of only one were read.
			skipped:  ambiguousCandidates > 1
				? [{
					what:   `${ambiguousCandidates - 1} other ${ambiguousCandidates - 1 === 1 ? 'entity' : 'entities'} named ${params.symbolName ?? target.name}`,
					reason: `the name is ambiguous and only the callers of ${target.file}:${target.startLine} were read`,
				}]
				: [],
		}),
		subject:         params.symbolName ?? target.name,
		targetEntityId:  target.id,
		callers:         hits,
	};
}

