function resolveRelativeToInsrcRoot(relativePath: string): string {
	const thisFile = fileURLToPath(import.meta.url);
	// .../analyze/explore/capability-reuse-check.js -> ... -> .../insrc
	const insrcRoot = resolve(thisFile, '..', '..', '..');
	return resolve(insrcRoot, relativePath);
}

function pickTopDistinct<T extends { path: string; kind: string; score: number }>(
	hits: readonly T[],
	limit: number,
): T[] {
	const chosen: T[] = [];
	const seen = new Set<string>();
	// Prefer dir hits over file hits for the same directory prefix.
	const sorted = [...hits].sort((a, b) => {
		if (a.kind !== b.kind) return a.kind === 'dir' ? -1 : 1;
		return b.score - a.score;
	});
	for (const h of sorted) {
		if (seen.has(h.path)) continue;
		seen.add(h.path);
		chosen.push(h);
		if (chosen.length >= limit) break;
	}
	return chosen;
}

function basenameOf(path: string): string {
	const trimmed = path.replace(/\/$/, '');
	const idx = trimmed.lastIndexOf('/');
	return idx >= 0 ? trimmed.slice(idx + 1) : trimmed;
}

function parseParams(exp: Exploration): ClassHierarchyParams {
	const p = exp.params as Record<string, unknown>;
	const symbolName = typeof p['symbolName'] === 'string'
		? (p['symbolName'] as string).trim()
		: undefined;
	const entityId = typeof p['entityId'] === 'string'
		? (p['entityId'] as string).trim()
		: undefined;
	if ((symbolName === undefined || symbolName.length === 0)
	 && (entityId   === undefined || entityId.length   === 0)) {
		throw new Error(
			'class.hierarchy: one of params.symbolName or params.entityId is required',
		);
	}
	return {
		...(symbolName !== undefined && symbolName.length > 0 ? { symbolName } : {}),
		...(entityId   !== undefined && entityId.length   > 0 ? { entityId }   : {}),
	};
}

async function hydrate(idMap: Map<bigint, string>): Promise<Entity[]> {
		const stringIds: string[] = [];
		for (const sid of idMap.values()) stringIds.push(sid);
		if (stringIds.length === 0) return [];
		return getEntitiesByIds(db, stringIds);
	}

function isTestPath(path: string): boolean {
	return TEST_PATH_RX.test(path);
}

function densityScore(entityCount: number): number {
	if (entityCount <= 0)   return 0;
	if (entityCount < 10)   return 0.25;
	if (entityCount < 50)   return 0.5;
	if (entityCount < 250)  return 0.75;
	return 1.0;
}

function hasPrefixMatch(q: string, bag: ReadonlySet<string>): boolean {
	if (q.length < MIN_PREFIX_LEN) return false;
	const qPrefix = q.slice(0, MIN_PREFIX_LEN);
	for (const t of bag) {
		if (t.length < MIN_PREFIX_LEN) continue;
		if (t.startsWith(qPrefix))                    return true;
		if (q.startsWith(t.slice(0, MIN_PREFIX_LEN))) return true;
	}
	return false;
}

function tokenise(query: string): string[] {
	return query.toLowerCase()
		.split(/[^a-z0-9_]+/g)
		.filter(t => t.length >= 2 && !STOPWORDS.has(t));
}

function splitIdentifier(name: string): string[] {
	// First collapse extension separators + slashes to spaces, then
	// split camelCase: any lowercase-to-uppercase or letter-to-digit
	// transition becomes a boundary.
	const collapsed = name
		.replace(/([a-z])([A-Z])/g, '$1 $2')
		.replace(/([A-Z])([A-Z][a-z])/g, '$1 $2')
		.replace(/([a-zA-Z])(\d)/g, '$1 $2')
		.replace(/(\d)([a-zA-Z])/g, '$1 $2');
	return collapsed
		.split(/[^a-zA-Z0-9]+/g)
		.filter(t => t.length >= 2)
		.map(t => t.toLowerCase());
}

function scoreCandidate(
	c:      Candidate,
	tokens: readonly string[],
	repoPath: string,
	structuralBoost: boolean,
): ScoredCandidate | null {
	if (tokens.length === 0) return null;

	// Tokenise the path (walk every path segment, split each on
	// identifier boundaries). Same for the name.
	const relPath = c.path.startsWith(repoPath) ? c.path.slice(repoPath.length + 1) : c.path;
	const pathTokens = new Set<string>();
	for (const seg of relPath.split(/[\\/]+/g)) {
		for (const t of splitIdentifier(seg)) pathTokens.add(t);
	}
	const nameTokens = new Set(splitIdentifier(c.name));

	// Count query tokens that appear in path / name. Exact match
	// scores 1; prefix match (>=7-char shared prefix in both
	// directions) scores 0.7 -- lets `classifier` still hit
	// `classification/` (share "classifi" = 8 chars), `extract` hit
	// `extraction/`, `payable` hit `payables/`, etc. Short tokens
	// (<7 chars) fall back to exact match only so we don't false-
	// match `class` -> `classroom`.
	let pathHits = 0;
	let nameHits = 0;
	for (const t of tokens) {
		if (pathTokens.has(t))       pathHits += 1;
		else if (hasPrefixMatch(t, pathTokens)) pathHits += 0.7;

		if (nameTokens.has(t))       nameHits += 1;
		else if (hasPrefixMatch(t, nameTokens)) nameHits += 0.7;
	}

	// No hits at all -> drop.
	if (pathHits === 0 && nameHits === 0) return null;

	const pathMatchNorm = pathHits / tokens.length;
	const nameMatchNorm = nameHits / tokens.length;

	// Depth is observed but not scored. See W_PATH_TOKENS block above
	// for the rationale: depth is a bad prior in real codebases where
	// docs cluster near the root and code sinks into modules. We keep
	// the segment count as a diagnostic so callers can still see it
	// in `diagnostics.pathDepth`, but it does not enter the score.
	const depthSegments = relPath.split(/[\\/]+/g).filter(x => x.length > 0).length;

	// Entity-density score: how much INDEXED code lives under this
	// candidate. For directories, this is the count of non-artefact
	// entities whose file path lives under the dir. For files, the
	// entity count IN the file. For entity hits, just 1. Density
	// discriminates real code modules from documentation-only dirs
	// that share a name.
	const density = densityScore(c.entityCount ?? 0);

	let score =
		W_PATH_TOKENS    * pathMatchNorm +
		W_NAME_TOKENS    * nameMatchNorm +
		W_ENTITY_DENSITY * density;

	if (structuralBoost && c.kind === 'dir') {
		score += DIR_STRUCTURAL_BONUS;
	}

	// Test-only paths are halved UNCONDITIONALLY -- see the
	// TEST_PATH_PENALTY constant above for why the structuralBoost
	// guard was removed. Test files should almost never rank #1
	// unless the query explicitly mentions tests.
	if (isTestPath(c.path)) {
		score *= TEST_PATH_PENALTY;
	}

	// Clamp to [0, 1] after bonuses.
	if (score > 1) score = 1;
	if (score < 0) score = 0;

	return {
		...c,
		score,
		diagnostics: {
			tokenMatch:    (pathMatchNorm + nameMatchNorm) / 2,
			pathDepth:     depthSegments,
			entityDensity: density,
		},
	};
}

internalHelpers.signature:
enumerateDirs(
	repoPath: string,
	ignoreFilter: import('../context/repo-ignore-filter.js').RepoIgnoreFilter,
	/** Directories and entries the walk could not read, for the completeness record. */
	skipped: SkippedItem[],
): Candidate[]

internalHelpers.body:
function enumerateDirs(
	repoPath: string,
	ignoreFilter: import('../context/repo-ignore-filter.js').RepoIgnoreFilter,
	/** Directories and entries the walk could not read, for the completeness record. */
	skipped: SkippedItem[],
): Candidate[] {
	const out: Candidate[] = [];
	function walk(dir: string, depth: number): void {
		if (depth > MAX_DIR_DEPTH) return;
		let entries: string[];
		try {
			entries = readdirSync(dir);
		} catch (err) {
			// The repository root itself: the lookup could not run. A directory
			// below it: expected on a real tree (permissions); it is named as skipped.
			if (depth === 0) throw err;
			skipped.push({ what: dir, reason: `the directory could not be read (${errorCode(err)})` });
			return;
		}
		for (const name of entries) {
			if (IGNORE_DIRS.has(name)) continue;
			if (name.startsWith('.') && depth === 0) continue;   // skip .git-like at root
			const full = join(dir, name);
			// Drop anything git considers gitignored (build/, dist/,
			// target/, out/, .next/, node_modules/, ...). The hardcoded
			// IGNORE_DIRS above is intentionally incomplete -- every
			// toolchain names its build dir differently. Delegating to
			// git guarantees the analyze surface matches the indexer's
			// view of the repo.
			if (!ignoreFilter.isIncluded(full)) continue;
			let s;
			try { s = statSync(full); }
			catch (err) {
				// Expected: a broken link, or an entry removed while the walk runs.
				skipped.push({ what: full, reason: `the entry could not be read (${errorCode(err)})` });
				continue;
			}
			if (!s.isDirectory()) continue;
			out.push({ kind: 'dir', path: full, name });
			walk(full, depth + 1);
		}
	}
	walk(repoPath, 0);
	return out;
}

function walk(dir: string, depth: number): void {
		if (depth > MAX_DIR_DEPTH) return;
		let entries: string[];
		try {
			entries = readdirSync(dir);
		} catch (err) {
			// The repository root itself: the lookup could not run. A directory
			// below it: expected on a real tree (permissions); it is named as skipped.
			if (depth === 0) throw err;
			skipped.push({ what: dir, reason: `the directory could not be read (${errorCode(err)})` });
			return;
		}
		for (const name of entries) {
			if (IGNORE_DIRS.has(name)) continue;
			if (name.startsWith('.') && depth === 0) continue;   // skip .git-like at root
			const full = join(dir, name);
			// Drop anything git considers gitignored (build/, dist/,
			// target/, out/, .next/, node_modules/, ...). The hardcoded
			// IGNORE_DIRS above is intentionally incomplete -- every
			// toolchain names its build dir differently. Delegating to
			// git guarantees the analyze surface matches the indexer's
			// view of the repo.
			if (!ignoreFilter.isIncluded(full)) continue;
			let s;
			try { s = statSync(full); }
			catch (err) {
				// Expected: a broken link, or an entry removed while the walk runs.
				skipped.push({ what: full, reason: `the entry could not be read (${errorCode(err)})` });
				continue;
			}
			if (!s.isDirectory()) continue;
			out.push({ kind: 'dir', path: full, name });
			walk(full, depth + 1);
		}
	}

function annotateEntityCounts(
	candidates: readonly Candidate[],
	entities:   readonly Entity[],
): Candidate[] {
	// Build a prefix index of directory paths -> counter for O(N +
	// K) instead of O(N * K). Every entity file walks up to the root
	// counting each ancestor dir.
	const dirCount = new Map<string, number>();
	const fileCount = new Map<string, number>();
	for (const e of entities) {
		if (e.artifact === true) continue;
		if (!STRUCTURAL_ENTITY_KINDS.has(e.kind) && e.kind !== 'file') continue;
		const file = e.file;
		if (e.kind === 'file') {
			// File entities contribute to dir counts up the chain but
			// not to their own file's structural count (only functions
			// / classes / etc do).
		} else {
			fileCount.set(file, (fileCount.get(file) ?? 0) + 1);
		}
		// Walk parent dirs.
		let cursor = parentDir(file);
		while (cursor.length > 0) {
			dirCount.set(cursor, (dirCount.get(cursor) ?? 0) + 1);
			const next = parentDir(cursor);
			if (next === cursor) break;
			cursor = next;
		}
	}
	// Only structural (non-file) entities get counted in the dir
	// aggregates above -- files that hold structural entities were
	// already contributing via their child structurals. But we also
	// want files themselves to contribute a small signal for
	// entity-count-oriented dirs, so top up each dir by the number
	// of files with kind='file' underneath it.
	// (Simplification: for V1 the structural-only count is
	// meaningful enough; skip the file top-up. Revisit when Phase 4
	// convention.detect wants finer signal.)
	const out: Candidate[] = [];
	for (const c of candidates) {
		let count = 0;
		if (c.kind === 'dir')    count = dirCount.get(c.path)  ?? 0;
		else if (c.kind === 'file') count = fileCount.get(c.path) ?? 0;
		else                    count = 1;  // entity itself
		out.push({ ...c, entityCount: count });
	}
	return out;
}

function parentDir(path: string): string {
	const idx = path.lastIndexOf('/');
	if (idx <= 0) return '';
	return path.slice(0, idx);
}

function fileCandidatesFromEntities(
	entities:     readonly Entity[],
	ignoreFilter: import('../context/repo-ignore-filter.js').RepoIgnoreFilter,
): Candidate[] {
	const out: Candidate[] = [];
	for (const e of entities) {
		if (e.kind !== 'file') continue;
		// Artefacts (markdown docs, YAML configs, etc.) are covered by
		// the docs retrieval pipeline. Exclude them from concept.resolve
		// candidates so a `.md` guide file named "messaging_module_
		// guide.md" doesn't beat the actual `insors/core/messaging/`
		// module on a code-target query.
		if (e.artifact === true) continue;
		// Drop stale entities that live under a currently-gitignored
		// path. The entity table can carry rows from prior indexing
		// runs where the path was still tracked; git is the source of
		// truth for what should surface *now*.
		if (!ignoreFilter.isIncluded(e.file)) continue;
		out.push({
			kind: 'file',
			path: e.file,
			name: basename(e.file),
		});
	}
	return out;
}

function structuralEntityCandidates(
	entities:     readonly Entity[],
	ignoreFilter: import('../context/repo-ignore-filter.js').RepoIgnoreFilter,
): Candidate[] {
	const out: Candidate[] = [];
	for (const e of entities) {
		if (!STRUCTURAL_ENTITY_KINDS.has(e.kind)) continue;
		if (e.artifact === true) continue;
		// Same stale-entity filter as fileCandidatesFromEntities: a
		// function/class living under a currently-gitignored path
		// (`out/`, `build/`, `dist/`, ...) is a build artefact and must
		// not surface as a candidate.
		if (!ignoreFilter.isIncluded(e.file)) continue;
		out.push({
			kind:     'entity',
			path:     e.file,
			name:     e.name,
			entityId: e.id,
		});
	}
	return out;
}

function parseParams(exp: Exploration): ConceptResolveParams {
	const p = exp.params as Record<string, unknown>;
	const query = typeof p['query'] === 'string' ? (p['query'] as string).trim() : '';
	if (query.length === 0) {
		throw new Error(`concept.resolve: params.query is required (non-empty string)`);
	}
	const limit = typeof p['limit'] === 'number' && p['limit']! > 0
		? Math.min(MAX_HITS, Math.floor(p['limit'] as number))
		: MAX_HITS;
	const includeKindsRaw = p['includeKinds'];
	const includeKinds = Array.isArray(includeKindsRaw)
		? includeKindsRaw.filter(k => k === 'dir' || k === 'file' || k === 'entity') as ('dir' | 'file' | 'entity')[]
		: undefined;
	return {
		query,
		limit,
		...(includeKinds !== undefined ? { includeKinds } : {}),
	};
}

function errorCode(err: unknown): string {
	return (err as NodeJS.ErrnoException).code ?? (err instanceof Error ? err.message : String(err));
}

function noQueryCompleteness(): Completeness {
	return buildCompleteness({
		returned: 0, basis: 'graph', notEstablished: true,
		basisNote: `${GRAPH_BASIS_NOTE}. The query held no distinctive word to match, so no search was made`,
	});
}

function parseParams(exp: Exploration): ConfigTraceParams {
	const p = exp.params as Record<string, unknown>;
	const key = typeof p['key'] === 'string' ? (p['key'] as string).trim() : '';
	if (key.length === 0) {
		throw new Error('config.trace: params.key is required (non-empty string)');
	}
	const topK = typeof p['topK'] === 'number' && p['topK']! > 0
		? Math.min(MAX_TOP_K, Math.floor(p['topK'] as number))
		: DEFAULT_TOP_K;
	const path = typeof p['path'] === 'string' && (p['path'] as string).length > 0
		? (p['path'] as string)
		: undefined;
	return {
		key,
		topK,
		...(path !== undefined ? { path } : {}),
	};
}

function escapeRegex(s: string): string {
	return s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

function extname(p: string): string {
	const idx = p.lastIndexOf('.');
	if (idx < 0) return '';
	const slashIdx = p.lastIndexOf('/');
	if (idx < slashIdx) return '';
	return p.slice(idx);
}

function scopedPath(candidate: string, repoRoot: string): string {
	const normRoot = repoRoot.replace(/\/+$/, '');
	if (!candidate.startsWith('/')) {
		return `${normRoot}/${candidate.replace(/^\/+/, '')}`;
	}
	const norm = candidate.replace(/\/+$/, '');
	if (norm === normRoot || norm.startsWith(`${normRoot}/`)) return norm;
	throw new Error(`config.trace: params.path='${candidate}' is not inside repoPath='${repoRoot}'`);
}

function parseParams(exp: Exploration): ConventionDetectParams {
	const p = exp.params as Record<string, unknown>;
	const path = typeof p['path'] === 'string' ? (p['path'] as string).trim() : '';
	if (path.length === 0) {
		throw new Error('convention.detect: params.path is required (non-empty absolute directory path)');
	}
	return { path };
}

function computeNamingSchema(entities: readonly Entity[]): ConventionNamingSchema {
	const fnBreak = emptyBreakdown();
	const clsBreak = emptyBreakdown();
	const fileBreak = emptyBreakdown();
	const testFileSeen: Record<TestFileConvention, number> = {
		'test_*': 0, '*_test': 0, '*.spec': 0, '*.test': 0,
		'inline': 0, 'none': 0, 'mixed': 0,
	};

	const seenFiles = new Set<string>();
	let fnCount = 0, clsCount = 0, fileCount = 0;
	let anyTest = false;

	for (const e of entities) {
		if (e.kind === 'function' || e.kind === 'method') {
			fnCount++;
			bump(fnBreak, classifyName(e.name));
		} else if (e.kind === 'class' || e.kind === 'interface') {
			clsCount++;
			bump(clsBreak, classifyName(e.name));
		}
		if (!seenFiles.has(e.file)) {
			seenFiles.add(e.file);
			fileCount++;
			const bn = basename(e.file, extname(e.file));
			bump(fileBreak, classifyName(bn));
			const tc = classifyTestFile(e.file);
			if (tc !== 'none') {
				anyTest = true;
				testFileSeen[tc] = (testFileSeen[tc] ?? 0) + 1;
			}
		}
	}

	return {
		functions:          dominant(fnBreak),
		functionsBreakdown: fnBreak,
		classes:            dominant(clsBreak),
		classesBreakdown:   clsBreak,
		files:              dominant(fileBreak),
		filesBreakdown:     fileBreak,
		testFiles:          anyTest ? dominantTestFile(testFileSeen) : 'none',
		sampleSizes: {
			functions: fnCount,
			classes:   clsCount,
			files:     fileCount,
		},
	};
}

function emptyBreakdown(): Record<string, number> {
	return {
		snake_case: 0,
		camelCase:  0,
		PascalCase: 0,
		'kebab-case': 0,
		mixed:      0,
		unknown:    0,
	};
}

function emptyNamingSchema(): ConventionNamingSchema {
	return {
		functions:          'unknown',
		functionsBreakdown: emptyBreakdown(),
		classes:            'unknown',
		classesBreakdown:   emptyBreakdown(),
		files:              'unknown',
		filesBreakdown:     emptyBreakdown(),
		testFiles:          'none',
		sampleSizes: { functions: 0, classes: 0, files: 0 },
	};
}

function dominant(breakdown: Record<string, number>): NamingCase {
	const total = Object.values(breakdown).reduce((a, b) => a + b, 0)
		- (breakdown['unknown'] ?? 0);
	if (total === 0) return 'unknown';
	const entries = Object.entries(breakdown)
		.filter(([k]) => k !== 'unknown' && k !== 'mixed')
		.sort((a, b) => b[1] - a[1]);
	const [topKey, topCount] = entries[0]!;
	const runnerCount = entries[1]?.[1] ?? 0;
	if (topCount / total >= DOMINANCE_MIN_SHARE
		&& (runnerCount === 0 || topCount / runnerCount >= DOMINANCE_MIN_RATIO)) {
		return topKey as NamingCase;
	}
	return 'mixed';
}

function classifyTestFile(file: string): TestFileConvention {
	const bn = basename(file);
	const stem = basename(file, extname(file));
	if (bn.endsWith('.spec.ts') || bn.endsWith('.spec.js') || bn.endsWith('.spec.tsx') || bn.endsWith('.spec.jsx')) return '*.spec';
	if (bn.endsWith('.test.ts') || bn.endsWith('.test.js') || bn.endsWith('.test.tsx') || bn.endsWith('.test.jsx')) return '*.test';
	if (stem.startsWith('test_')) return 'test_*';
	if (stem.endsWith('_test'))   return '*_test';
	// Files inside a canonical test directory whose basename doesn't
	// match a convention -- treat as inline test.
	if (/(^|\/)(tests?|__tests__|test|spec|specs)\//i.test(file)) return 'inline';
	return 'none';
}

function dominantTestFile(counts: Record<TestFileConvention, number>): TestFileConvention {
	const entries = Object.entries(counts)
		.filter(([k]) => k !== 'none' && k !== 'mixed')
		.sort((a, b) => b[1] - a[1]);
	const total = entries.reduce((a, [, c]) => a + c, 0);
	if (total === 0) return 'none';
	const [topKey, topCount] = entries[0]!;
	const runner = entries[1]?.[1] ?? 0;
	if (topCount / total >= DOMINANCE_MIN_SHARE
		&& (runner === 0 || topCount / runner >= DOMINANCE_MIN_RATIO)) {
		return topKey as TestFileConvention;
	}
	return 'mixed';
}

async function computeBaseClassIdioms(
	under: readonly Entity[],
	db:    Awaited<ReturnType<typeof getDb>>,
	path:  string,
): Promise<BaseClassIdiomScan> {
	// Only classes / interfaces / types can serve as bases. Walk each
	// entity's INHERITS-out edges; aggregate to the base + its
	// in-module subclasses.
	const classesInModule = under.filter(e =>
		e.kind === 'class' || e.kind === 'interface' || e.kind === 'type',
	);
	if (classesInModule.length === 0) return { idioms: [], totalIdioms: 0, mostSubclasses: 0, noGraphNode: [] };

	const inModuleIds = new Set(classesInModule.map(e => e.id));

	// Map baseName -> { baseEntityId?, subs: Entity[] }
	const idiomMap = new Map<string, { baseEntityId?: string; subs: Entity[] }>();

	const noGraphNode: Entity[] = [];
	for (const sub of classesInModule) {
		const u64 = await entityU64ForId(sub.id);
		if (u64 === undefined) { noGraphNode.push(sub); continue; }
		const inheritsOut = await outNeighbors(u64, { kindFilter: ['INHERITS'] });
		if (inheritsOut.length === 0) continue;
		const idMap = await entityIdsByU64s(inheritsOut);
		const baseIds = Array.from(idMap.values());
		const baseEnts = baseIds.length > 0 ? await getEntitiesByIds(db, baseIds) : [];
		for (const base of baseEnts) {
			// Skip when the base itself lives inside the same module --
			// this is intra-module refinement, not an "idiom to notice."
			// Idioms are cross-module bases the module leans on.
			if (base.file.startsWith(path.endsWith('/') ? path : path + '/')
				|| base.file === path) {
				continue;
			}
			// Skip when the base is an artefact.
			if (base.artifact === true) continue;
			const key = base.name;
			const slot = idiomMap.get(key);
			if (slot === undefined) {
				idiomMap.set(key, { baseEntityId: base.id, subs: [sub] });
			} else {
				slot.subs.push(sub);
			}
		}
	}

	// Also walk INHERITS-in for each in-module class to catch
	// "abstract base in this module has many external subclasses" --
	// but those are cross-module TOO, so we'd have to broaden the
	// scan. Keep it to the direct-out view for V1.
	void inNeighbors; void inModuleIds;

	const idioms = Array.from(idiomMap.entries())
		.map(([baseName, slot]): ConventionBaseClassIdiom => {
			const reprs = slot.subs
				.slice(0, MAX_REPR_SUBCLASSES)
				.map(e => e.name);
			return {
				baseName,
				...(slot.baseEntityId !== undefined ? { baseEntityId: slot.baseEntityId } : {}),
				subclassCount:             slot.subs.length,
				representativeSubclasses:  reprs,
			};
		})
		.sort((a, b) => b.subclassCount - a.subclassCount)
		.slice(0, MAX_BASE_CLASS_IDIOMS);

	let mostSubclasses = 0;
	for (const slot of idiomMap.values()) mostSubclasses = Math.max(mostSubclasses, slot.subs.length);
	return { idioms, totalIdioms: idiomMap.size, mostSubclasses, noGraphNode };
}

function isDunder(name: string): boolean {
	return name.length >= 4 && name.startsWith('__') && name.endsWith('__');
