async function profileDir(
	dir:      string,
	entities: readonly Entity[],
	ignoreFilter: import('../context/repo-ignore-filter.js').RepoIgnoreFilter,
	measurer:   ItemMeasurer,
	partlyRead: PartlyReadItem[],
	skipped:    SkippedItem[],
): Promise<ModuleProfile> {
	// Immediate children (subdirs + files) via filesystem.
	const subdirs: string[] = [];
	const filesInDir: Array<{
		file: string;
		language: string;
		bytes: number;
		kind: string;
	}> = [];
	// The directory was stat'd a moment ago. If it cannot be listed the lookup
	// could not run: this throws, and the executor reports it as failed.
	const entries: string[] = readdirSync(dir);
	for (const name of entries) {
		if (IGNORE_DIRS.has(name)) continue;
		if (name.startsWith('.') && name !== '.env.example') continue;
		const full = join(dir, name);
		// .gitignore-aware filter. See analyze/context/repo-ignore-
		// filter.ts -- drops anything not tracked by git (out/, build/,
		// dist/, target/, .next/, node_modules/, ...). Permissive for
		// non-git repos, so the IGNORE_DIRS set above still guards.
		if (!ignoreFilter.isIncluded(full)) continue;
		let s;
		try { s = statSync(full); }
		catch (err) {
			// Expected: a broken link, or an entry removed while the listing runs.
			skipped.push({ what: full, reason: `the entry could not be read (${(err as NodeJS.ErrnoException).code ?? (err as Error).message})` });
			continue;
		}
		if (s.isDirectory()) {
			subdirs.push(full);
		} else if (s.isFile()) {
			const entity = findFileEntity(entities, full);
			filesInDir.push({
				file:     full,
				language: entity?.language ?? '',
				bytes:    s.size,
				kind:     entity?.kind ?? 'file',
			});
		}
	}
	subdirs.sort();
	filesInDir.sort((a, b) => a.file.localeCompare(b.file));

	// Exports: read entities in index files (__init__.py, index.ts,
	// etc.) directly under `dir` -- functions + classes + variables
	// that are `isExported`.
	const exports: string[] = [];
	for (const f of filesInDir) {
		if (!INDEX_FILENAMES.has(basename(f.file))) continue;
		for (const e of entities) {
			if (e.file !== f.file) continue;
			if (e.kind === 'file' || e.kind === 'module') continue;
			if (e.isExported === true) {
				exports.push(e.name);
			}
		}
	}
	exports.sort();

	// Entrypoints: files matching an INDEX_FILENAMES basename OR
	// whose body triggers an ENTRYPOINT_MARKER regex. Body match
	// requires reading the file entity's body (already indexed).
	const entrypoints: string[] = [];
	for (const f of filesInDir) {
		if (INDEX_FILENAMES.has(basename(f.file))) {
			entrypoints.push(f.file);
			continue;
		}
		const bodyMatchEntity = entities.find(e => e.file === f.file && e.kind === 'file');
		const body = (bodyMatchEntity?.body ?? '').slice(0, ENTRYPOINT_SCAN_CHARS);
		if (body.length === 0) continue;
		let found = false;
		for (const rx of ENTRYPOINT_MARKERS) {
			if (rx.test(body)) {
				entrypoints.push(f.file);
				found = true;
				break;
			}
		}
		// A marker past the scanned part would have been missed.
		if (!found && bodyMatchEntity !== undefined) {
			const cut = await measurer.partlyRead(f.file, bodyMatchEntity, body.length);
			if (cut !== undefined) partlyRead.push(cut);
		}
	}

	// entityCount + totalBytes across the WHOLE subtree, not just
	// direct children. Non-artefact structural entities.
	const dirWithSep = dir.endsWith(sep) ? dir : dir + sep;
	let entityCount = 0;
	let totalBytes  = 0;
	for (const e of entities) {
		if (e.artifact === true) continue;
		if (e.kind === 'file') {
			if (e.file === dir || e.file.startsWith(dirWithSep)) {
				try {
					totalBytes += statSync(e.file).size;
				} catch {
					// Expected: the index still holds a file that is no longer on disk.
					skipped.push({ what: e.file, reason: 'the file is in the index and no longer on disk; totalBytes does not count it' });
				}
			}
			continue;
		}
		if (e.file === dir || e.file.startsWith(dirWithSep)) {
			entityCount += 1;
		}
	}

	return {
		path:        dir,
		kind:        'dir',
		subdirs,
		filesInDir,
		exports,
		entrypoints,
		entityCount,
		totalBytes,
	};
}

async function profileFile(
	file:       string,
	entities:   readonly Entity[],
	measurer:   ItemMeasurer,
	partlyRead: PartlyReadItem[],
): Promise<ModuleProfile> {
	// The file was stat'd a moment ago; if it is gone now the lookup could not run.
	const size = statSync(file).size;
	const fileEntity = entities.find(e => e.kind === 'file' && e.file === file);
	const exports: string[] = [];
	let entityCount = 0;
	for (const e of entities) {
		if (e.file !== file) continue;
		if (e.artifact === true) continue;
		if (e.kind === 'file' || e.kind === 'module') continue;
		entityCount += 1;
		if (e.isExported === true) exports.push(e.name);
	}
	exports.sort();
	const body = (fileEntity?.body ?? '').slice(0, ENTRYPOINT_SCAN_CHARS);
	const entrypoints: string[] = [];
	if (INDEX_FILENAMES.has(basename(file))) entrypoints.push(file);
	else {
		for (const rx of ENTRYPOINT_MARKERS) {
			if (rx.test(body)) { entrypoints.push(file); break; }
		}
		// A marker past the scanned part would have been missed.
		if (entrypoints.length === 0 && fileEntity !== undefined && body.length > 0) {
			const cut = await measurer.partlyRead(file, fileEntity, body.length);
			if (cut !== undefined) partlyRead.push(cut);
		}
	}
	return {
		path:        file,
		kind:        'file',
		subdirs:     [],
		filesInDir:  [{
			file,
			language: fileEntity?.language ?? extname(file).slice(1),
			bytes:    size,
			kind:     fileEntity?.kind ?? 'file',
		}],
		exports,
		entrypoints,
		entityCount,
		totalBytes:  size,
	};
}

function findFileEntity(entities: readonly Entity[], file: string): Entity | undefined {
	for (const e of entities) {
		if (e.kind === 'file' && e.file === file) return e;
	}
	return undefined;
}

function parseParams(exp: Exploration): SearchTextParams {
	const p = exp.params as Record<string, unknown>;
	const pattern = typeof p['pattern'] === 'string' ? (p['pattern'] as string).trim() : '';
	if (pattern.length === 0) {
		throw new Error('search.text: params.pattern is required (non-empty regex string)');
	}
	const glob = typeof p['glob'] === 'string' && (p['glob'] as string).length > 0
		? (p['glob'] as string)
		: undefined;
	const caseInsensitive = p['caseInsensitive'] === true;
	const topK = typeof p['topK'] === 'number' && p['topK']! > 0
		? Math.min(MAX_TOP_K, Math.floor(p['topK'] as number))
		: DEFAULT_TOP_K;
	const path = typeof p['path'] === 'string' && (p['path'] as string).length > 0
		? (p['path'] as string)
		: undefined;
	return {
		pattern,
		...(glob !== undefined ? { glob } : {}),
		caseInsensitive,
		topK,
		...(path !== undefined ? { path } : {}),
	};
}

function resolveScopedPath(candidate: string, repoRoot: string): string {
	const normRoot = repoRoot.replace(/\/+$/, '');
	// If the caller supplied a repo-relative segment, prepend the
	// repo root. Otherwise validate the absolute path is under the
	// root.
	if (!candidate.startsWith('/')) {
		return `${normRoot}/${candidate.replace(/^\/+/, '')}`;
	}
	const norm = candidate.replace(/\/+$/, '');
	if (norm === normRoot || norm.startsWith(`${normRoot}/`)) {
		return norm;
	}
	throw new Error(
		`search.text: params.path='${candidate}' is not inside repoPath='${repoRoot}'`,
	);
}

function parseParams(exp: Exploration): SymbolLocateParams {
	const p = exp.params as Record<string, unknown>;
	const namesRaw = p['names'];
	if (!Array.isArray(namesRaw) || namesRaw.length === 0) {
		throw new Error('symbol.locate: params.names is required (non-empty string[])');
	}
	const names = namesRaw
		.filter(n => typeof n === 'string')
		.map(n => (n as string).trim())
		.filter(n => n.length >= 2);
	if (names.length === 0) {
		throw new Error('symbol.locate: params.names contained no valid entries');
	}
	const kindsRaw = p['kinds'];
	const kinds = Array.isArray(kindsRaw)
		? kindsRaw.filter(k => typeof k === 'string') as EntityKind[]
		: undefined;
	const limit = typeof p['limit'] === 'number' && p['limit']! > 0
		? Math.min(MAX_LIMIT, Math.floor(p['limit'] as number))
		: DEFAULT_LIMIT;
	const matchMode = p['matchMode'] === 'substring' ? 'substring' : 'exact';
	return {
		names,
		kinds: kinds ?? DEFAULT_KINDS,
		limit,
		matchMode,
	};
}

function mergeUnique(a: readonly Entity[], b: readonly Entity[]): Entity[] {
	const seen = new Set<string>();
	const out: Entity[] = [];
	for (const list of [a, b]) {
		for (const e of list) {
			if (seen.has(e.id)) continue;
			seen.add(e.id);
			out.push(e);
		}
	}
	return out;
}

function parseParams(exp: Exploration): TestLocateParams {
	const p = exp.params as Record<string, unknown>;
	const subject = typeof p['subject'] === 'string' ? (p['subject'] as string).trim() : '';
	if (subject.length === 0) {
		throw new Error('test.locate: params.subject is required (non-empty string)');
	}
	const topK = typeof p['topK'] === 'number' && p['topK']! > 0
		? Math.min(MAX_TOP_K, Math.floor(p['topK'] as number))
		: DEFAULT_TOP_K;
	return { subject, topK };
}

function tokenise(subject: string): string[] {
	const raw = subject
		.replace(/([a-z0-9])([A-Z])/g, '$1_$2')  // camelCase splitter
		.toLowerCase()
		.split(/[^a-z0-9]+/)
		.filter(t => t.length >= 3 && !STOP.has(t));
	return Array.from(new Set(raw));
}

function parseParams(exp: Exploration): UsageExampleParams {
	const p = exp.params as Record<string, unknown>;
	const symbolName = typeof p['symbolName'] === 'string'
		? (p['symbolName'] as string).trim()
		: undefined;
	const entityId = typeof p['entityId'] === 'string'
		? (p['entityId'] as string).trim()
		: undefined;
	if ((symbolName === undefined || symbolName.length === 0)
	 && (entityId   === undefined || entityId.length   === 0)) {
		throw new Error(
			'usage.example: one of params.symbolName or params.entityId is required',
		);
	}
	const kindsRaw = p['kinds'];
	const kinds = Array.isArray(kindsRaw)
		? kindsRaw.filter(k => typeof k === 'string') as EntityKind[]
		: undefined;
	const topK = typeof p['topK'] === 'number' && p['topK']! > 0
		? Math.min(MAX_TOP_K, Math.floor(p['topK'] as number))
		: DEFAULT_TOP_K;
	return {
		...(symbolName !== undefined && symbolName.length > 0 ? { symbolName } : {}),
		...(entityId   !== undefined && entityId.length   > 0 ? { entityId }   : {}),
		...(kinds      !== undefined && kinds.length > 0     ? { kinds }      : {}),
		topK,
	};
}
